(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[9] = {"grade":9,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 9, tập 1","c":[{"t":"Chương I. Phương trình và hệ hai phương trình bậc nhất hai ẩn","l":[{"t":"Bài 1. Khái niệm phương trình và hệ hai phương trình bậc nhất hai ẩn","req":["Nhận biết phương trình bậc nhất hai ẩn, hệ hai phương trình bậc nhất hai ẩn và nghiệm của chúng."],"sum":["Phương trình bậc nhất hai ẩn x, y có dạng ax + by = c, trong đó a, b, c là các số đã biết, a ≠ 0 hoặc b ≠ 0.","Khái niệm: Phương trình bậc nhất hai ẩn x, y có dạng ax + by = c, trong đó a, b, c là các số đã biết, a ≠ 0 hoặc b ≠ 0.","Phương trình bậc nhất hai ẩn luôn có vô số nghiệm: Trên mặt phẳng toạ độ, tập nghiệm được biểu diễn bởi một đường thẳng ax + by = c.","Cặp số (x₀; y₀) là nghiệm của…: Cặp số (x₀; y₀) là nghiệm của hệ nếu nó là nghiệm của cả hai phương trình."],"e":["Hay nhầm: Có x² nên không bậc nhất.","Hay nhầm: Phải có a ≠ 0 hoặc b ≠ 0."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 2. Giải hệ hai phương trình bậc nhất hai ẩn","req":["Giải hệ hai phương trình bậc nhất hai ẩn bằng phương pháp thế, phương pháp cộng đại số; dùng máy tính cầm tay."],"m":[{"t":"Giải hệ hai phương trình bậc nhất hai ẩn","w":"Đề cho hệ hai phương trình bậc nhất hai ẩn x, y và yêu cầu tìm nghiệm hoặc biểu thức theo nghiệm.","s":["Chọn phương pháp: thế (khi một ẩn có hệ số 1 hoặc −1) hoặc cộng đại số (khi hệ số của một ẩn bằng nhau hoặc đối nhau, hoặc nhân để được như vậy).","Biến đổi để được một phương trình chỉ chứa một ẩn.","Giải phương trình đó, thế ngược vào một phương trình của hệ để tìm ẩn còn lại.","Kiểm tra nghiệm trong cả hai phương trình và kết luận nghiệm (x; y)."],"n":["Khi cộng đại số, nhân cả hai vế của phương trình, không chỉ một vế.","Cùng dấu thì trừ vế với vế, đối dấu thì cộng vế với vế để mất một ẩn.","Nghiệm phải thỏa mãn cả hai phương trình; hãy thử lại."]}],"sum":["Phương pháp thế: từ một phương trình biểu diễn một ẩn theo ẩn kia, thế vào phương trình còn lại để được phương trình một ẩn; giải rồi suy ra ẩn còn lại.","Phương pháp thế: Từ một phương trình biểu diễn một ẩn theo ẩn kia, thế vào phương trình còn lại để được phương trình một ẩn; giải rồi suy ra ẩn còn lại.","Phương pháp cộng đại số: Nhân hai vế mỗi phương trình với số thích hợp để hệ số của một ẩn bằng nhau hoặc đối nhau; cộng hoặc trừ từng vế để khử ẩn đó.","Hệ hai phương trình bậc nhất hai…: Hệ hai phương trình bậc nhất hai ẩn có thể có một nghiệm duy nhất, vô nghiệm hoặc vô số nghiệm.","Có thể dùng máy tính cầm tay…: Có thể dùng máy tính cầm tay (chế độ giải hệ phương trình) để tìm nghiệm."],"d":["Giải hệ hai phương trình bậc nhất hai ẩn"],"e":["Hay nhầm: Hệ số y đối nhau nên cộng.","Hay nhầm: Hai đường thẳng song song.","Lưu ý: Khi cộng đại số, nhân cả hai vế của phương trình, không chỉ một vế.","Lưu ý: Cùng dấu thì trừ vế với vế, đối dấu thì cộng vế với vế để mất một ẩn.","Lưu ý: Nghiệm phải thỏa mãn cả hai phương trình; hãy thử lại."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 3. Giải bài toán bằng cách lập hệ phương trình","req":["Giải bài toán thực tế bằng cách lập hệ hai phương trình bậc nhất hai ẩn."],"m":[{"t":"Giải bài toán bằng cách lập hệ phương trình","w":"Bài toán có lời văn có hai đại lượng chưa biết (hai số, giá tiền, chuyển động xuôi ngược dòng, hình chữ nhật...).","s":["Chọn hai ẩn x, y (kèm đơn vị) và đặt điều kiện thích hợp.","Biểu diễn các đại lượng theo x, y; dựa vào hai mối quan hệ trong đề để lập hai phương trình.","Giải hệ phương trình vừa lập.","Đối chiếu nghiệm với điều kiện, trả lời đúng câu hỏi của đề."],"n":["Mỗi ẩn cần một phương trình riêng, đề thường cho đúng hai dữ kiện.","Xuôi dòng: vận tốc = vận tốc riêng + vận tốc dòng nước; ngược dòng: vận tốc = vận tốc riêng − vận tốc dòng nước.","Đơn vị phải thống nhất (nghìn đồng, giờ, km)."]}],"sum":["Các bước: (1) Lập hệ phương trình: chọn hai ẩn và đặt điều kiện thích hợp; biểu diễn các đại lượng chưa biết theo ẩn; lập hai phương trình.","Các bước: Lập hệ phương trình: chọn hai ẩn và đặt điều kiện thích hợp; biểu diễn các đại lượng chưa biết theo ẩn; lập hai phương trình.","Các dạng thường gặp: Toán tìm hai số; chuyển động; năng suất, công việc; mua bán; phần trăm; hình học; hoá học (pha trộn, phản ứng)."],"d":["Giải bài toán bằng cách lập hệ phương trình"],"e":["Lưu ý: Mỗi ẩn cần một phương trình riêng, đề thường cho đúng hai dữ kiện.","Lưu ý: Xuôi dòng: vận tốc = vận tốc riêng + vận tốc dòng nước; ngược dòng: vận tốc = vận tốc riêng − vận tốc dòng nước.","Lưu ý: Đơn vị phải thống nhất (nghìn đồng, giờ, km)."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":6,"Vận dụng":5}}}]},{"t":"Chương II. Phương trình và bất phương trình bậc nhất một ẩn","l":[{"t":"Bài 4. Phương trình quy về phương trình bậc nhất một ẩn","req":["Giải phương trình tích dạng (ax + b)(cx + d) = 0; giải phương trình chứa ẩn ở mẫu quy về bậc nhất."],"m":[{"t":"Giải phương trình tích và phương trình chứa ẩn ở mẫu","w":"Đề cho phương trình dạng (ax + b)(cx + d) = 0 hoặc phương trình có ẩn x ở mẫu.","s":["Phương trình tích: đưa về dạng A(x)·B(x) = 0 (chuyển vế, phân tích thành nhân tử).","Phương trình tích: giải A(x) = 0 và B(x) = 0, mọi nghiệm đều là nghiệm.","Phương trình chứa ẩn ở mẫu: tìm điều kiện xác định (mẫu khác 0), quy đồng, khử mẫu rồi giải phương trình nhận được.","Đối chiếu từng nghiệm với điều kiện xác định, loại nghiệm làm mẫu bằng 0, kết luận."],"n":["Không chia hai vế cho biểu thức chứa x vì sẽ mất nghiệm.","Luôn đối chiếu nghiệm với điều kiện xác định sau khi khử mẫu.","Khử mẫu chỉ được khi nhân hai vế với biểu thức khác 0 (đã có điều kiện)."]}],"sum":["Phương trình tích (ax + b)(cx + d) = 0 tương đương ax + b = 0 hoặc cx + d = 0. Ta giải hai phương trình rồi lấy tất cả các nghiệm.","Khái niệm: Phương trình tích (ax + b)(cx + d) = 0 tương đương ax + b = 0 hoặc cx + d = 0.","Phương trình chứa ẩn ở mẫu: Tìm điều kiện xác định (mọi mẫu khác 0)"],"d":["Giải phương trình tích và phương trình chứa ẩn ở mẫu"],"e":["Lưu ý: Không chia hai vế cho biểu thức chứa x vì sẽ mất nghiệm.","Lưu ý: Luôn đối chiếu nghiệm với điều kiện xác định sau khi khử mẫu.","Lưu ý: Khử mẫu chỉ được khi nhân hai vế với biểu thức khác 0 (đã có điều kiện)."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 5. Bất đẳng thức và tính chất","req":["Nhận biết bất đẳng thức; vận dụng tính chất liên hệ giữa thứ tự với phép cộng, phép nhân."],"sum":["Hệ thức dạng a > b (a < b, a ≥ b, a ≤ b) gọi là bất đẳng thức; a là vế trái, b là vế phải.","Khái niệm: Hệ thức dạng a > b (a < b, a ≥ b, a ≤ b) gọi là bất đẳng thức; a là vế trái, b là vế phải.","Tính chất bắc cầu: A > b và b > c ⇒ a > c.","Liên hệ với phép cộng: A > b ⇒ a + c > b + c (cộng cùng một số vào hai vế, chiều không đổi).","Liên hệ với phép nhân: A > b, c > 0 ⇒ ac > bc; a > b, c < 0 ⇒ ac < bc (nhân với số âm phải đổi chiều)."],"e":["Hay nhầm: Nhân với số âm phải đổi chiều.","Hay nhầm: Cộng trừ không đổi chiều.","Hay nhầm: Nhân với 2 > 0 không đổi chiều."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 6. Bất phương trình bậc nhất một ẩn","req":["Nhận biết bất phương trình bậc nhất một ẩn; giải bất phương trình bậc nhất một ẩn."],"m":[{"t":"Giải bất phương trình bậc nhất một ẩn","w":"Đề cho bất phương trình dạng ax + b < 0 (hoặc >, ≤, ≥) và hỏi nghiệm, nghiệm nguyên lớn nhất, nhỏ nhất, số nghiệm nguyên.","s":["Bỏ ngoặc, quy đồng khử mẫu (mẫu dương) nếu có.","Chuyển các hạng tử chứa x về một vế, hằng số về vế kia (chuyển vế đổi dấu).","Thu gọn về dạng ax > b (hoặc <, ≥, ≤) rồi chia hai vế cho a: nếu a < 0 thì đổi chiều bất đẳng thức.","Viết nghiệm dạng x > m (hoặc ...) và chọn các số nguyên thỏa mãn theo yêu cầu."],"n":["Nhân hoặc chia hai vế cho số âm phải đổi chiều bất đẳng thức.","Dấu \"<\", \">\" không lấy giá trị biên; \"≤\", \"≥\" lấy giá trị biên.","Đọc kĩ yêu cầu: nguyên lớn nhất, nguyên nhỏ nhất, nguyên dương."]}],"sum":["Bất phương trình bậc nhất một ẩn x có dạng ax + b > 0 (hoặc <, ≥, ≤), a ≠ 0.","Khái niệm: Bất phương trình bậc nhất một ẩn x có dạng ax + b > 0 (hoặc <, ≥, ≤), a ≠ 0.","Quy tắc chuyển vế: Chuyển một hạng tử từ vế này sang vế kia và đổi dấu hạng tử đó.","Quy tắc nhân: Nhân hai vế với cùng một số khác 0; giữ nguyên chiều nếu số đó dương, đổi chiều nếu số đó âm.","Giải ax + b > 0: Nếu a > 0 thì x > −b/a; nếu a < 0 thì x < −b/a."],"d":["Giải bất phương trình bậc nhất một ẩn"],"e":["Hay nhầm: Chỉ khi nhân với số dương.","Lưu ý: Nhân hoặc chia hai vế cho số âm phải đổi chiều bất đẳng thức.","Lưu ý: Dấu \"<\", \">\" không lấy giá trị biên; \"≤\", \"≥\" lấy giá trị biên.","Lưu ý: Đọc kĩ yêu cầu: nguyên lớn nhất, nguyên nhỏ nhất, nguyên dương."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}}]},{"t":"Chương III. Căn bậc hai và căn bậc ba","l":[{"t":"Bài 7. Căn bậc hai và căn thức bậc hai","req":["Nhận biết căn bậc hai, căn bậc hai số học; tính căn bậc hai; nhận biết căn thức bậc hai và điều kiện xác định."],"sum":["Căn bậc hai của số thực a không âm là số x sao cho x² = a. Số dương a có đúng hai căn bậc hai là √a và −√a; số 0 có một căn bậc hai là 0; số âm không có căn bậc hai.","Căn bậc hai của số thực a không âm là số x sao cho x² = a: Số dương a có đúng hai căn bậc hai là √a và −√a; số 0 có một căn bậc hai là 0; số âm không có căn bậc hai.","√a (a ≥ 0) gọi là căn…: √a (a ≥ 0) gọi là căn bậc hai số học của a.","Với A là biểu thức đại số…: Với A là biểu thức đại số, √A gọi là căn thức bậc hai; √A xác định khi A ≥ 0."],"e":["Hay nhầm: Căn bậc hai số học không âm.","Hay nhầm: Đó là hai căn bậc hai của 81.","Hay nhầm: Số âm không có căn bậc hai.","Hay nhầm: Căn bậc hai số học không âm."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 8. Khai căn bậc hai với phép nhân và phép chia","req":["Vận dụng quy tắc khai căn một tích, một thương; nhân, chia các căn bậc hai."],"sum":["Quy tắc trên mở rộng cho tích nhiều số không âm. Có thể dùng để tính nhanh, ví dụ √(16·25) = 4·5 = 20; √2·√8 = √16 = 4.","Công thức","Quy tắc trên mở rộng cho tích nhiều số không âm: Có thể dùng để tính nhanh, ví dụ √(16·25) = 4·5 = 20; √2·√8 = √16 = 4."],"e":["Hay nhầm: Không đúng với phép cộng.","Hay nhầm: Cần không âm và b khác 0."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 9. Biến đổi đơn giản và rút gọn biểu thức chứa căn thức bậc hai","req":["Đưa thừa số ra ngoài, vào trong dấu căn; trục căn thức ở mẫu; rút gọn biểu thức chứa căn."],"m":[{"t":"Biến đổi và rút gọn biểu thức chứa căn bậc hai","w":"Đề cho biểu thức có căn bậc hai và yêu cầu tính, rút gọn hoặc tính giá trị tại một số.","s":["Tìm điều kiện để các căn có nghĩa (biểu thức dưới căn không âm, mẫu khác 0).","Đưa thừa số ra ngoài dấu căn hoặc vào trong, trục căn thức ở mẫu nếu cần.","Phân tích tử và mẫu thành nhân tử rồi rút gọn nhân tử chung.","Thay giá trị (nếu đề cho) và tính, kiểm tra giá trị thỏa điều kiện."],"n":["√(a²) = |a|, không phải a.","√a·√b = √(ab) và √a/√b = √(a/b) chỉ đúng khi a ≥ 0 và b > 0 (hoặc b ≥ 0 với phép nhân).","(√a + b)(√a − b) = a − b²: dùng hằng đẳng thức để nhanh hơn."]}],"sum":["Đưa thừa số vào trong dấu căn: a√b = √(a²b) với a ≥ 0; a√b = −√(a²b) với a < 0.","Công thức","Đưa thừa số vào trong dấu căn: A√b = √(a²b) với a ≥ 0; a√b = −√(a²b) với a < 0.","Trục căn thức ở mẫu: A/√B = A√B/B (B > 0);","Rút gọn: Đưa về các căn đồng dạng rồi cộng, trừ; ví dụ √12 + √27 = 2√3 + 3√3 = 5√3."],"d":["Biến đổi và rút gọn biểu thức chứa căn bậc hai"],"e":["Lưu ý: √(a²) = |a|, không phải a.","Lưu ý: √a·√b = √(ab) và √a/√b = √(a/b) chỉ đúng khi a ≥ 0 và b > 0 (hoặc b ≥ 0 với phép nhân).","Lưu ý: (√a + b)(√a − b) = a − b²: dùng hằng đẳng thức để nhanh hơn."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 10. Căn bậc ba và căn thức bậc ba","req":["Nhận biết căn bậc ba; tính căn bậc ba; nhận biết căn thức bậc ba."],"sum":["Căn bậc ba của số thực a là số x sao cho x³ = a, kí hiệu ∛a. Mỗi số thực đều có duy nhất một căn bậc ba.","Căn bậc ba của số thực a là số x sao cho x³ = a, kí hiệu ∛a: Mỗi số thực đều có duy nhất một căn bậc ba.","Căn bậc ba của số dương là…: Căn bậc ba của số dương là số dương, của số âm là số âm, của 0 là 0. ∛A xác định với mọi giá trị của A."],"e":["Hay nhầm: Căn bậc ba của số âm là số âm."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương IV. Hệ thức lượng trong tam giác vuông","l":[{"t":"Bài 11. Tỉ số lượng giác của góc nhọn","req":["Nhận biết tỉ số lượng giác sin, cos, tan, cot của góc nhọn; tỉ số lượng giác của góc 30°, 45°, 60°; hai góc phụ nhau."],"sum":["Trong tam giác vuông, với góc nhọn α:","Khái niệm: Trong tam giác vuông, với góc nhọn α:","Giá trị đặc biệt: Sin 30° = 1/2, cos 30° = √3/2, tan 45° = 1, sin 45° = cos 45° = √2/2, cos 60° = 1/2, tan 60° = √3.","Nếu α + β = 90° thì sin α = cos β, tan α = cot β: Với góc nhọn α: 0 < sin α < 1, 0 < cos α < 1."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 12. Một số hệ thức giữa cạnh, góc trong tam giác vuông và ứng dụng","req":["Vận dụng hệ thức giữa cạnh và góc trong tam giác vuông để giải tam giác vuông và giải bài toán thực tế."],"m":[{"t":"Giải tam giác vuông","w":"Đề cho một số cạnh hoặc góc của tam giác vuông và yêu cầu tính cạnh, góc hoặc tỉ số lượng giác.","s":["Vẽ hình, đánh dấu góc vuông, góc nhọn đã cho; xác định cạnh huyền, cạnh đối, cạnh kề với góc đang xét.","Chọn hệ thức: sin = đối/huyền, cos = kề/huyền, tan = đối/kề, cot = kề/đối; hoặc Pythagore BC² = AB² + AC².","Viết hệ thức chứa đại lượng cần tìm rồi tính.","Kiểm tra lại bằng Pythagore hoặc tổng hai góc nhọn bằng 90°."],"n":["Cạnh đối và cạnh kề thay đổi theo góc đang xét; luôn chỉ rõ góc.","Cạnh huyền là cạnh đối diện góc vuông và là cạnh lớn nhất.","sin của góc này bằng cos của góc phụ với nó."]}],"sum":["Trong tam giác vuông, mỗi cạnh góc vuông bằng: cạnh huyền nhân sin góc đối hoặc nhân cos góc kề; cạnh góc vuông kia nhân tan góc đối hoặc nhân cot góc kề.","Trong tam giác vuông, mỗi cạnh góc vuông bằng: Cạnh huyền nhân sin góc đối hoặc nhân cos góc kề; cạnh góc vuông kia nhân tan góc đối hoặc nhân cot góc kề.","Giải tam giác vuông là tìm tất…: Giải tam giác vuông là tìm tất cả các cạnh và góc khi biết hai yếu tố (trong đó ít nhất một cạnh).","Ứng dụng: Đo chiều cao cây, toà nhà; khoảng cách không đến được;"],"d":["Giải tam giác vuông"],"e":["Hay nhầm: Không xác định được cạnh.","Lưu ý: Cạnh đối và cạnh kề thay đổi theo góc đang xét; luôn chỉ rõ góc.","Lưu ý: Cạnh huyền là cạnh đối diện góc vuông và là cạnh lớn nhất.","Lưu ý: sin của góc này bằng cos của góc phụ với nó."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}}]},{"t":"Chương V. Đường tròn","l":[{"t":"Bài 13. Mở đầu về đường tròn","req":["Nhận biết đường tròn, vị trí tương đối của điểm với đường tròn; tâm và trục đối xứng của đường tròn."],"sum":["Đường tròn tâm O bán kính R (R > 0), kí hiệu (O; R), là hình gồm tất cả các điểm cách O một khoảng bằng R.","Đường tròn tâm O bán kính R (R > 0), kí hiệu (O: R), là hình gồm tất cả các điểm cách O một khoảng bằng R.","Điểm M nằm trên đường tròn khi…: Điểm M nằm trên đường tròn khi OM = R; nằm trong khi OM < R; nằm ngoài khi OM > R.","Đường tròn có tâm đối xứng là…: Đường tròn có tâm đối xứng là tâm của nó và có vô số trục đối xứng là các đường thẳng đi qua tâm.","Dây cung là đoạn thẳng nối hai điểm của đường tròn: Đường kính là dây đi qua tâm, dài bằng 2R và là dây lớn nhất."],"e":["Hay nhầm: Mọi đường kính đều là trục."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 14. Cung và dây của một đường tròn","req":["Nhận biết góc ở tâm, cung, số đo cung; liên hệ giữa dây và khoảng cách đến tâm."],"sum":["Góc ở tâm là góc có đỉnh trùng tâm đường tròn. Cung bị chắn bởi góc ở tâm; cung nhỏ có số đo bằng số đo góc ở tâm chắn cung đó; cung lớn có số đo bằng 360° trừ số đo cung nhỏ; nửa đường tròn có số…","Góc ở tâm là góc có đỉnh trùng tâm đường tròn: Cung bị chắn bởi góc ở tâm; cung nhỏ có số đo bằng số đo góc ở tâm chắn cung đó; cung lớn có số đo bằng 360° trừ số đo cung nhỏ; nửa đường tròn có…","Trong một đường tròn, đường kính vuông…: Trong một đường tròn, đường kính vuông góc với một dây thì đi qua trung điểm dây đó;","Hai dây bằng nhau thì cách đều…: Hai dây bằng nhau thì cách đều tâm; dây lớn hơn thì gần tâm hơn."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 15. Độ dài của cung tròn. Diện tích hình quạt tròn và hình vành khuyên","req":["Tính độ dài cung tròn, diện tích hình quạt tròn, hình vành khuyên."],"m":[{"t":"Tính độ dài cung, diện tích hình quạt tròn, số đo góc nội tiếp","w":"Đề cho bán kính R và số đo cung (hoặc góc ở tâm) và hỏi độ dài cung, diện tích hình quạt; hoặc hỏi góc nội tiếp chắn một cung.","s":["Xác định bán kính R và số đo n° của cung (số đo cung bằng số đo góc ở tâm chắn cung đó).","Độ dài cung: l = π·R·n/180. Diện tích hình quạt: S = π·R²·n/360 (hoặc S = l·R/2).","Góc nội tiếp bằng một nửa số đo cung bị chắn; góc nội tiếp chắn nửa đường tròn bằng 90°.","Thay số, giữ π trong kết quả (hoặc lấy gần đúng nếu đề yêu cầu), ghi đơn vị."],"n":["Số đo cung tính bằng độ; đừng nhầm với độ dài cung.","Hình quạt 90° bằng một phần tư hình tròn, 180° bằng nửa hình tròn.","Góc nội tiếp có số đo bằng nửa số đo góc ở tâm cùng chắn một cung."]}],"sum":["Hình vành khuyên giới hạn bởi hai đường tròn đồng tâm bán kính R > r có diện tích S = π(R² − r²).","Công thức","Hình vành khuyên giới hạn bởi hai…: Hình vành khuyên giới hạn bởi hai đường tròn đồng tâm bán kính R > r có diện tích S = π(R² − r²)."],"d":["Tính độ dài cung, diện tích hình quạt tròn, số đo góc nội tiếp"],"e":["Hay nhầm: Đó là diện tích hình quạt.","Lưu ý: Số đo cung tính bằng độ; đừng nhầm với độ dài cung.","Lưu ý: Hình quạt 90° bằng một phần tư hình tròn, 180° bằng nửa hình tròn.","Lưu ý: Góc nội tiếp có số đo bằng nửa số đo góc ở tâm cùng chắn một cung."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 16. Vị trí tương đối của đường thẳng và đường tròn","req":["Nhận biết ba vị trí tương đối của đường thẳng và đường tròn; tiếp tuyến và tính chất hai tiếp tuyến cắt nhau."],"sum":["Gọi d là khoảng cách từ tâm O đến đường thẳng a. Nếu d < R thì a cắt đường tròn tại hai điểm; d = R thì a tiếp xúc đường tròn (a là tiếp tuyến); d > R thì a và đường tròn không giao nhau.","Gọi d là khoảng cách từ tâm O đến đường thẳng a: Nếu d < R thì a cắt đường tròn tại hai điểm; d = R thì a tiếp xúc đường tròn (a là tiếp tuyến); d > R thì a và đường tròn không giao nhau.","Tiếp tuyến vuông góc với bán kính tại tiếp điểm: Ngược lại, đường thẳng đi qua một điểm của đường tròn và vuông góc với bán kính tại điểm đó là tiếp tuyến.","Hai tiếp tuyến cắt nhau tại M (MA, MB là tiếp tuyến): MA = MB;"],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 17. Vị trí tương đối của hai đường tròn","req":["Nhận biết vị trí tương đối của hai đường tròn qua đoạn nối tâm và bán kính."],"sum":["Cho (O; R) và (O′; r), R ≥ r, d = OO′.","Cho (O: R) và (O′; r), R ≥ r, d = OO′.","Tiếp xúc ngoài khi d = R…: Tiếp xúc ngoài khi d = R + r; tiếp xúc trong khi d = R − r > 0 (1 điểm chung).","Không giao nhau: Ở ngoài nhau khi d > R + r;","Hai đường tròn cắt nhau thì đường…: Hai đường tròn cắt nhau thì đường nối tâm là đường trung trực của dây chung."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Toán 9, tập 2","c":[{"t":"Chương VI. Hàm số y = ax² (a ≠ 0). Phương trình bậc hai một ẩn","l":[{"t":"Bài 18. Hàm số y = ax² (a ≠ 0)","req":["Tính giá trị của hàm số y = ax²; nhận biết tính chất và vẽ đồ thị hàm số y = ax² (a ≠ 0)."],"sum":["Hàm số y = ax² (a ≠ 0) xác định với mọi x. Nếu a > 0: y ≥ 0 với mọi x, giá trị nhỏ nhất y = 0 tại x = 0.","Hàm số y = ax² (a ≠ 0) xác định với mọi x: Nếu a > 0: y ≥ 0 với mọi x, giá trị nhỏ nhất y = 0 tại x = 0.","Đồ thị hàm số y = ax²…: Đồ thị hàm số y = ax² là một đường cong (parabol) đi qua gốc O, nhận Oy làm trục đối xứng;","Điểm M(x₀; y₀) thuộc đồ thị khi…: Điểm M(x₀; y₀) thuộc đồ thị khi y₀ = a·x₀²."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 19. Phương trình bậc hai một ẩn","req":["Nhận biết phương trình bậc hai một ẩn; giải bằng công thức nghiệm, công thức nghiệm thu gọn; dùng máy tính cầm tay."],"m":[{"t":"Giải phương trình bậc hai ax² + bx + c = 0","w":"Đề cho phương trình bậc hai và yêu cầu giải, xét số nghiệm hoặc tìm điều kiện của tham số để có nghiệm kép, hai nghiệm phân biệt.","s":["Xác định các hệ số a, b, c (a khác 0), đưa phương trình về dạng chuẩn.","Tính biệt thức Δ = b² − 4ac (hoặc Δ′ = b′² − ac với b = 2b′).","Xét dấu: Δ < 0 vô nghiệm; Δ = 0 nghiệm kép x = −b/(2a); Δ > 0 hai nghiệm x = (−b ± √Δ)/(2a).","Với bài tìm tham số: lập điều kiện về Δ rồi giải."],"n":["Phải đưa phương trình về một vế bằng 0 trước khi xác định a, b, c.","Giữ dấu của b và c khi thay vào Δ; b² luôn không âm.","Nghiệm kép là hai nghiệm bằng nhau, chỉ ghi một giá trị."]}],"sum":["Phương trình bậc hai một ẩn có dạng ax² + bx + c = 0 (a ≠ 0).","Khái niệm: Phương trình bậc hai một ẩn có dạng ax² + bx + c = 0 (a ≠ 0).","Công thức nghiệm thu gọn khi b = 2b′: Δ′ = b′² − ac: Δ′ > 0: x₁,₂ = (−b′ ± √Δ′)/a.","Trường hợp đặc biệt: C = 0 thì đưa về x(ax + b) = 0; b = 0 thì x² = −c/a."],"d":["Giải phương trình bậc hai ax² + bx + c = 0"],"e":["Lưu ý: Phải đưa phương trình về một vế bằng 0 trước khi xác định a, b, c.","Lưu ý: Giữ dấu của b và c khi thay vào Δ; b² luôn không âm.","Lưu ý: Nghiệm kép là hai nghiệm bằng nhau, chỉ ghi một giá trị."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 20. Định lí Viète và ứng dụng","req":["Vận dụng định lí Viète để tính tổng, tích nghiệm; nhẩm nghiệm; tìm hai số biết tổng và tích."],"m":[{"t":"Định lí Viète và tính biểu thức đối xứng của hai nghiệm","w":"Đề cho phương trình bậc hai có hai nghiệm x₁, x₂ và hỏi tổng, tích hoặc giá trị biểu thức như x₁² + x₂².","s":["Kiểm tra phương trình có nghiệm: Δ ≥ 0 (hoặc a, c trái dấu).","Tính tổng S = x₁ + x₂ = −b/a và tích P = x₁·x₂ = c/a.","Biến đổi biểu thức cần tính theo S và P: x₁² + x₂² = S² − 2P; (x₁ − x₂)² = S² − 4P; 1/x₁ + 1/x₂ = S/P.","Thay S, P và tính; kiểm tra điều kiện của đề."],"n":["Phải có Δ ≥ 0 trước khi dùng Viète với nghiệm thực.","Dấu của S là −b/a: cẩn thận với dấu của b.","|x₁ − x₂| = √(S² − 4P), nhớ lấy căn dương."]}],"sum":["Nếu x₁, x₂ là hai nghiệm của ax² + bx + c = 0 (a ≠ 0) thì:","Khái niệm: Nếu x₁, x₂ là hai nghiệm của ax² + bx + c = 0 (a ≠ 0) thì:","Nhẩm nghiệm: Nếu a + b + c = 0 thì x₁ = 1, x₂ = c/a; nếu a − b + c = 0 thì x₁ = −1, x₂ = −c/a.","Hai số có tổng S và tích…: Hai số có tổng S và tích P là nghiệm của phương trình x² − Sx + P = 0 (điều kiện S² − 4P ≥ 0)."],"d":["Định lí Viète và tính biểu thức đối xứng của hai nghiệm"],"e":["Lưu ý: Phải có Δ ≥ 0 trước khi dùng Viète với nghiệm thực.","Lưu ý: Dấu của S là −b/a: cẩn thận với dấu của b.","Lưu ý: |x₁ − x₂| = √(S² − 4P), nhớ lấy căn dương."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 21. Giải bài toán bằng cách lập phương trình","req":["Giải bài toán thực tế bằng cách lập phương trình bậc hai một ẩn."],"m":[{"t":"Giải bài toán bằng cách lập phương trình bậc hai","w":"Bài toán có lời văn dẫn đến phương trình bậc hai (tích hai số, diện tích hình chữ nhật, tổng bình phương...).","s":["Chọn ẩn x (kèm đơn vị) và đặt điều kiện cho x.","Biểu diễn các đại lượng khác theo x, tìm quan hệ bằng nhau để lập phương trình bậc hai.","Giải phương trình (công thức nghiệm hoặc nhẩm nghiệm).","Đối chiếu từng nghiệm với điều kiện của x, loại nghiệm không phù hợp rồi trả lời."],"n":["Điều kiện của ẩn thường là số tự nhiên, số dương; nghiệm âm bị loại.","Hai nghiệm đều có thể thỏa: khi đó trả lời cả hai trường hợp nếu đề cho phép.","Diện tích hình chữ nhật = dài × rộng; chu vi cho biết tổng hai kích thước."]}],"sum":["Các bước: chọn ẩn, đặt điều kiện; biểu diễn các đại lượng theo ẩn; lập phương trình; giải phương trình;","Các bước: Chọn ẩn, đặt điều kiện; biểu diễn các đại lượng theo ẩn; lập phương trình; giải phương trình;","Các dạng thường gặp: Diện tích hình học; chuyển động; năng suất; số học (tích hai số liên tiếp); tăng trưởng phần trăm."],"d":["Giải bài toán bằng cách lập phương trình bậc hai"],"e":["Lưu ý: Điều kiện của ẩn thường là số tự nhiên, số dương; nghiệm âm bị loại.","Lưu ý: Hai nghiệm đều có thể thỏa: khi đó trả lời cả hai trường hợp nếu đề cho phép.","Lưu ý: Diện tích hình chữ nhật = dài × rộng; chu vi cho biết tổng hai kích thước."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":6}}}]},{"t":"Chương VII. Tần số và tần số tương đối","l":[{"t":"Bài 22. Bảng tần số và biểu đồ tần số","req":["Lập bảng tần số; biểu diễn bằng biểu đồ tần số dạng cột hoặc đoạn thẳng."],"sum":["Tần số của một giá trị là số lần giá trị đó xuất hiện trong mẫu dữ liệu. Bảng tần số gồm hai dòng (hoặc hai cột): giá trị và tần số tương ứng; tổng các tần số bằng cỡ mẫu n.","Khái niệm: Tần số của một giá trị là số lần giá trị đó xuất hiện trong mẫu dữ liệu.","Biểu đồ tần số dạng cột: Mỗi giá trị ứng với một cột có chiều cao bằng tần số.","Từ bảng tần số có thể tính số trung bình: X̄ = (x₁n₁ + x₂n₂ + … + xₖnₖ)/n."],"e":["Hay nhầm: Đó là tổng tần số tương đối (%)."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 23. Bảng tần số tương đối và biểu đồ tần số tương đối","req":["Lập bảng tần số tương đối; vẽ biểu đồ tần số tương đối dạng cột, hình quạt tròn."],"sum":["Tần số tương đối của giá trị x là tỉ số giữa tần số m của x và cỡ mẫu n, thường viết dưới dạng phần trăm.","Khái niệm: Tần số tương đối của giá trị x là tỉ số giữa tần số m của x và cỡ mẫu n, thường viết dưới dạng phần trăm.","Tổng các tần số tương đối bằng 100%: Biểu đồ hình quạt tròn: mỗi giá trị ứng với một hình quạt có góc ở tâm bằng f·360°."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 24. Bảng tần số, tần số tương đối ghép nhóm và biểu đồ","req":["Lập bảng tần số, tần số tương đối ghép nhóm; vẽ biểu đồ tần số dạng cột, đoạn thẳng cho số liệu ghép nhóm."],"sum":["Khi dữ liệu có nhiều giá trị, ta ghép thành các nhóm dạng nửa khoảng [a; b), b − a là độ dài nhóm.","Khái niệm: Khi dữ liệu có nhiều giá trị, ta ghép thành các nhóm dạng nửa khoảng [a; b), b − a là độ dài nhóm.","Giá trị đại diện của nhóm [a…: Giá trị đại diện của nhóm [a; b) là trung điểm (a + b)/2.","Bảng tần số tương đối ghép nhóm…: Bảng tần số tương đối ghép nhóm có thêm dòng tần số tương đối của từng nhóm; biểu đồ tần số ghép nhóm dạng cột vẽ các cột liền nhau."],"e":["Hay nhầm: Nửa khoảng không chứa 30."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương VIII. Xác suất của biến cố trong một số mô hình xác suất đơn giản","l":[{"t":"Bài 25. Phép thử ngẫu nhiên và không gian mẫu","req":["Nhận biết phép thử ngẫu nhiên, không gian mẫu; mô tả không gian mẫu bằng liệt kê, bảng, sơ đồ cây."],"sum":["Phép thử ngẫu nhiên là hoạt động mà ta không biết trước kết quả. Tập hợp tất cả các kết quả có thể xảy ra gọi là không gian mẫu, kí hiệu Ω.","Khái niệm: Phép thử ngẫu nhiên là hoạt động mà ta không biết trước kết quả.","Mô tả không gian mẫu: Liệt kê; lập bảng (khi phép thử gồm hai thành phần, ví dụ gieo hai xúc xắc); vẽ sơ đồ cây (khi phép thử gồm nhiều bước).","Ví dụ: Tung hai đồng xu: Ω = {SS;"],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 26. Xác suất của biến cố liên quan tới phép thử","req":["Tính xác suất của biến cố bằng cách đếm số kết quả thuận lợi khi các kết quả đồng khả năng."],"m":[{"t":"Tính xác suất của biến cố trong phép thử ngẫu nhiên","w":"Đề cho phép thử (gieo xúc xắc, đồng xu, chọn số) và hỏi xác suất của một biến cố.","s":["Xác định phép thử và liệt kê không gian mẫu Ω (tất cả kết quả có thể, đồng khả năng); với hai lần thử dùng bảng hoặc cặp.","Gọi biến cố E và liệt kê các kết quả thuận lợi cho E.","P(E) = số kết quả thuận lợi / số phần tử của không gian mẫu.","Rút gọn phân số và kiểm tra 0 ≤ P(E) ≤ 1."],"n":["Gieo hai xúc xắc có 36 kết quả; (2; 5) và (5; 2) là hai kết quả khác nhau.","Đếm đủ, đếm đúng không trùng các kết quả thuận lợi.","P(không E) = 1 − P(E)."]}],"sum":["Biến cố liên quan tới phép thử là tập con của không gian mẫu. Mỗi kết quả làm cho biến cố xảy ra gọi là kết quả thuận lợi.","Biến cố liên quan tới phép thử là tập con của không gian mẫu: Mỗi kết quả làm cho biến cố xảy ra gọi là kết quả thuận lợi.","Công thức trên dùng khi các kết quả có thể là đồng khả năng: 0 ≤ P(A) ≤ 1; biến cố chắc chắn có xác suất 1; biến cố không thể có xác suất 0."],"d":["Tính xác suất của biến cố trong phép thử ngẫu nhiên"],"e":["Lưu ý: Gieo hai xúc xắc có 36 kết quả; (2; 5) và (5; 2) là hai kết quả khác nhau.","Lưu ý: Đếm đủ, đếm đúng không trùng các kết quả thuận lợi.","Lưu ý: P(không E) = 1 − P(E)."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":6,"Vận dụng":5}}}]},{"t":"Chương IX. Đường tròn ngoại tiếp và đường tròn nội tiếp","l":[{"t":"Bài 27. Góc nội tiếp","req":["Nhận biết góc nội tiếp; vận dụng liên hệ giữa góc nội tiếp và cung bị chắn."],"sum":["Góc nội tiếp là góc có đỉnh nằm trên đường tròn và hai cạnh chứa hai dây cung của đường tròn đó.","Khái niệm: Góc nội tiếp là góc có đỉnh nằm trên đường tròn và hai cạnh chứa hai dây cung của đường tròn đó.","Hệ quả: Các góc nội tiếp cùng chắn một cung (hoặc chắn các cung bằng nhau) thì bằng nhau; góc nội tiếp chắn nửa đường tròn là góc vuông; góc nội tiếp (≤…"],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 28. Đường tròn ngoại tiếp và đường tròn nội tiếp của một tam giác","req":["Xác định tâm và bán kính đường tròn ngoại tiếp, nội tiếp tam giác; tính bán kính với tam giác vuông, tam giác đều."],"sum":["Đường tròn ngoại tiếp tam giác đi qua ba đỉnh; tâm là giao điểm ba đường trung trực. Tam giác vuông có tâm đường tròn ngoại tiếp là trung điểm cạnh huyền, R bằng nửa cạnh huyền.","Khái niệm: Đường tròn ngoại tiếp tam giác đi qua ba đỉnh; tâm là giao điểm ba đường trung trực.","Đường tròn nội tiếp tam giác tiếp…: Đường tròn nội tiếp tam giác tiếp xúc với ba cạnh; tâm là giao điểm ba đường phân giác trong.","Với tam giác đều, tâm đường tròn…: Với tam giác đều, tâm đường tròn ngoại tiếp và nội tiếp trùng nhau (trọng tâm), R = 2r."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 29. Tứ giác nội tiếp","req":["Nhận biết tứ giác nội tiếp; vận dụng tính chất tổng hai góc đối bằng 180°."],"sum":["Tứ giác nội tiếp là tứ giác có bốn đỉnh nằm trên một đường tròn.","Khái niệm: Tứ giác nội tiếp là tứ giác có bốn đỉnh nằm trên một đường tròn.","Ngược lại, tứ giác có tổng hai…: Ngược lại, tứ giác có tổng hai góc đối bằng 180° thì nội tiếp được đường tròn."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 30. Đa giác đều","req":["Nhận biết đa giác đều; phép quay giữ nguyên đa giác đều."],"sum":["Đa giác đều là đa giác có tất cả các cạnh bằng nhau và tất cả các góc bằng nhau. Mỗi đa giác đều có đường tròn ngoại tiếp và nội tiếp cùng tâm.","Khái niệm: Đa giác đều là đa giác có tất cả các cạnh bằng nhau và tất cả các góc bằng nhau.","Phép quay tâm O góc α biến…: Phép quay tâm O góc α biến điểm M thành M′ với OM′ = OM và góc MOM′ = α."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài 31. Hình trụ và hình nón","req":["Nhận biết hình trụ, hình nón; tính diện tích xung quanh, thể tích hình trụ và hình nón."],"sum":["Hình trụ tạo thành khi quay hình chữ nhật một vòng quanh một cạnh; hình nón tạo thành khi quay tam giác vuông một vòng quanh một cạnh góc vuông.","Công thức","Hình trụ tạo thành khi quay hình…: Hình trụ tạo thành khi quay hình chữ nhật một vòng quanh một cạnh; hình nón tạo thành khi quay tam giác vuông một vòng quanh một cạnh góc vuông."],"e":["Hay nhầm: Diện tích xung quanh hình nón.","Hay nhầm: Diện tích xung quanh hình trụ."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 32. Hình cầu","req":["Nhận biết hình cầu, mặt cầu; tính diện tích mặt cầu và thể tích hình cầu."],"sum":["Khi quay nửa hình tròn tâm O bán kính R một vòng quanh đường kính, ta được hình cầu tâm O bán kính R; nửa đường tròn tạo nên mặt cầu.","Khái niệm: Khi quay nửa hình tròn tâm O bán kính R một vòng quanh đường kính, ta được hình cầu tâm O bán kính R; nửa đường tròn tạo nên mặt cầu.","Cắt hình cầu bởi mặt phẳng được…: Cắt hình cầu bởi mặt phẳng được hình tròn; mặt phẳng qua tâm cắt theo hình tròn lớn có bán kính R."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Phương trình và hệ hai phương trình bậc nhất hai ẩn","l":[{"t":"Bài tập nâng cao · Chương I. Phương trình và hệ hai phương trình bậc nhất hai ẩn (9 câu)","q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương II. Phương trình và bất phương trình bậc nhất một ẩn","l":[{"t":"Bài tập nâng cao · Chương II. Phương trình và bất phương trình bậc nhất một ẩn (9 câu)","q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương III. Căn bậc hai và căn bậc ba","l":[{"t":"Bài tập nâng cao · Chương III. Căn bậc hai và căn bậc ba (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương IV. Hệ thức lượng trong tam giác vuông","l":[{"t":"Bài tập nâng cao · Chương IV. Hệ thức lượng trong tam giác vuông (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương V. Đường tròn","l":[{"t":"Bài tập nâng cao · Chương V. Đường tròn (15 câu)","q":{"n":15,"lv":{"Nâng cao":15}}}]},{"t":"Chương VI. Hàm số y = ax² (a ≠ 0). Phương trình bậc hai một ẩn","l":[{"t":"Bài tập nâng cao · Chương VI. Hàm số y = ax² (a ≠ 0). Phương trình bậc hai một ẩn (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương VII. Tần số và tần số tương đối","l":[{"t":"Bài tập nâng cao · Chương VII. Tần số và tần số tương đối (9 câu)","q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương VIII. Xác suất của biến cố trong một số mô hình xác suất đơn giản","l":[{"t":"Bài tập nâng cao · Chương VIII. Xác suất của biến cố trong một số mô hình xác suất đơn giản (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương IX. Đường tròn ngoại tiếp và đường tròn nội tiếp","l":[{"t":"Bài tập nâng cao · Chương IX. Đường tròn ngoại tiếp và đường tròn nội tiếp (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài tập nâng cao · Chương X. Một số hình khối trong thực tiễn (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 9","c":[{"t":"Mở đầu","l":[{"t":"Bài 1. Nhận biết một số dụng cụ, hoá chất. Thuyết trình một vấn đề khoa học","req":["Nhận biết được một số dụng cụ và hoá chất sử dụng trong môn KHTN 9; trình bày được các bước viết và thuyết trình một vấn đề khoa học."],"sum":["Dụng cụ thường dùng: biến áp nguồn, ampe kế, vôn kế, joulemeter, điện trở, biến trở, nam châm, cuộn dây, lăng kính, thấu kính, đèn laser; các dụng cụ thuỷ tinh (ống nghiệm, cốc, bình tam giác, đèn…","Dụng cụ thường dùng: Biến áp nguồn, ampe kế, vôn kế, joulemeter, điện trở, biến trở, nam châm, cuộn dây, lăng kính, thấu kính, đèn laser; các dụng cụ thuỷ tinh (ống…","Hoá chất: Kim loại (Na, Fe, Al, Cu), dung dịch acid, base, muối; hợp chất hữu cơ (ethanol, acetic acid, glucose, saccharose).","Viết và thuyết trình một vấn đề khoa học gồm: Xác định vấn đề; thu thập thông tin; xử lí thông tin; viết báo cáo (mở đầu, nội dung, kết luận, tài liệu tham khảo); chuẩn bị bài trình chiếu và…"],"e":["Hay nhầm: Sodium phản ứng mạnh với nước."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương I. Năng lượng cơ học","l":[{"t":"Bài 2. Động năng. Thế năng","req":["Viết được biểu thức tính động năng, thế năng trọng trường; tính được động năng, thế năng."],"m":[{"t":"Tính động năng, thế năng","w":"Đề cho khối lượng, vận tốc, độ cao và hỏi động năng, thế năng hoặc so sánh.","s":["Đổi đơn vị: m (kg), v (m/s), h (m).","Động năng Wđ = ½·m·v²; thế năng Wt = 10·m·h.","Thay số, tính bình phương vận tốc trước khi nhân.","Ghi kết quả với đơn vị jun (J)."],"n":["Bình phương chỉ áp dụng cho v, không áp dụng cho cả ½mv.","Đổi tốc độ km/h sang m/s trước khi tính.","Vận tốc tăng gấp đôi thì động năng tăng gấp bốn."]}],"sum":["Năng lượng vật có được do chuyển động gọi là động năng. Động năng phụ thuộc vào khối lượng và tốc độ của vật.","Năng lượng vật có được do chuyển động gọi là động năng: Động năng phụ thuộc vào khối lượng và tốc độ của vật.","Năng lượng vật có được khi ở…: Năng lượng vật có được khi ở một độ cao so với vị trí khác được chọn làm gốc gọi là thế năng trọng trường."],"d":["Tính động năng, thế năng"],"e":["Lưu ý: Bình phương chỉ áp dụng cho v, không áp dụng cho cả ½mv.","Lưu ý: Đổi tốc độ km/h sang m/s trước khi tính.","Lưu ý: Vận tốc tăng gấp đôi thì động năng tăng gấp bốn."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":4}}},{"t":"Bài 3. Cơ năng","req":["Nêu được cơ năng là tổng động năng và thế năng; vận dụng sự chuyển hoá và bảo toàn cơ năng."],"sum":["Cơ năng của vật bằng tổng động năng và thế năng của nó.","Khái niệm: Cơ năng của vật bằng tổng động năng và thế năng của nó.","Trong quá trình chuyển động, động năng…: Trong quá trình chuyển động, động năng và thế năng có thể chuyển hoá qua lại.","Ví dụ: Vật rơi, độ cao giảm (thế năng giảm), tốc độ tăng (động năng tăng); con lắc dao động."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Công và công suất","req":["Nêu được công cơ học, công suất; tính được công, công suất trong trường hợp đơn giản."],"m":[{"t":"Tính công và công suất","w":"Đề cho lực, quãng đường, thời gian và hỏi công, công suất, hoặc thời gian thực hiện.","s":["Đổi đơn vị: F (N), s (m), t (s).","Công A = F·s (lực cùng phương chuyển dời).","Công suất P = A/t.","Bài nâng vật: lực nâng bằng trọng lượng P = 10·m; ghi đơn vị J, W."],"n":["Công chỉ có khi vật dịch chuyển theo phương của lực.","Nâng vật lên cao h: A = P·h.","1 kW = 1 000 W; 1 phút = 60 s."]}],"sum":["Công cơ học được thực hiện khi có lực tác dụng vào vật và làm vật dịch chuyển theo phương của lực.","Khái niệm: Công cơ học được thực hiện khi có lực tác dụng vào vật và làm vật dịch chuyển theo phương của lực.","Công suất là công thực hiện được…: Công suất là công thực hiện được trong một đơn vị thời gian, đặc trưng cho tốc độ thực hiện công."],"d":["Tính công và công suất"],"e":["Lưu ý: Công chỉ có khi vật dịch chuyển theo phương của lực.","Lưu ý: Nâng vật lên cao h: A = P·h.","Lưu ý: 1 kW = 1 000 W; 1 phút = 60 s."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4}}}]},{"t":"Chương II. Ánh sáng","l":[{"t":"Bài 5. Khúc xạ ánh sáng","req":["Nêu được hiện tượng khúc xạ ánh sáng; chiết suất; định luật khúc xạ ánh sáng."],"sum":["Hiện tượng khúc xạ ánh sáng là hiện tượng tia sáng bị gãy khúc (đổi hướng) khi truyền qua mặt phân cách giữa hai môi trường trong suốt khác nhau.","Khái niệm: Hiện tượng khúc xạ ánh sáng là hiện tượng tia sáng bị gãy khúc (đổi hướng) khi truyền qua mặt phân cách giữa hai môi trường trong suốt khác nhau.","Chiết suất của môi trường n =…: Chiết suất của môi trường n = c/v, trong đó c ≈ 3·10⁸ m/s là tốc độ ánh sáng trong chân không, v là tốc độ ánh sáng trong môi trường.","Định luật khúc xạ: Tia khúc xạ nằm trong mặt phẳng tới, ở bên kia pháp tuyến so với tia tới; với hai môi trường xác định, tỉ số giữa sin góc tới và sin góc khúc xạ là…"],"e":["Hay nhầm: Khi đi từ nước ra không khí."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Phản xạ toàn phần","req":["Nêu được hiện tượng phản xạ toàn phần, điều kiện xảy ra; ứng dụng (sợi quang)."],"sum":["Phản xạ toàn phần là hiện tượng toàn bộ tia sáng bị phản xạ trở lại môi trường cũ khi chiếu tới mặt phân cách giữa hai môi trường trong suốt.","Khái niệm: Phản xạ toàn phần là hiện tượng toàn bộ tia sáng bị phản xạ trở lại môi trường cũ khi chiếu tới mặt phân cách giữa hai môi trường trong suốt.","Điều kiện: Ánh sáng truyền từ môi trường có chiết suất lớn sang môi trường có chiết suất nhỏ hơn (n₁ > n₂) và góc tới lớn hơn hoặc bằng góc tới hạn.","Ứng dụng: Cáp quang (sợi quang) truyền tín hiệu thông tin, nội soi trong y học; lăng kính phản xạ toàn phần trong ống nhòm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Lăng kính","req":["Mô tả đường truyền tia sáng qua lăng kính; hiện tượng tán sắc ánh sáng; màu sắc của vật."],"sum":["Lăng kính là khối chất trong suốt, đồng chất, thường có dạng lăng trụ tam giác. Tia sáng đơn sắc đi qua lăng kính bị lệch về phía đáy lăng kính.","Khái niệm: Lăng kính là khối chất trong suốt, đồng chất, thường có dạng lăng trụ tam giác.","Ánh sáng trắng (ánh sáng Mặt Trời)…: Ánh sáng trắng (ánh sáng Mặt Trời) là hỗn hợp của nhiều ánh sáng màu.","Màu sắc của vật: Vật màu nào thì tán xạ (hắt lại) mạnh ánh sáng màu đó; vật màu trắng tán xạ tốt mọi ánh sáng; vật màu đen không tán xạ ánh sáng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Thấu kính","req":["Phân biệt thấu kính hội tụ, phân kì; vẽ ảnh qua thấu kính; xác định tính chất ảnh."],"sum":["Thấu kính hội tụ có phần rìa mỏng hơn phần giữa, chùm tia tới song song cho chùm ló hội tụ.","Khái niệm: Thấu kính hội tụ có phần rìa mỏng hơn phần giữa, chùm tia tới song song cho chùm ló hội tụ.","Các yếu tố: Trục chính, quang tâm O, tiêu điểm F, F′, tiêu cự f = OF.","Ba tia đặc biệt qua thấu kính hội tụ: Tia qua quang tâm truyền thẳng; tia song song trục chính cho tia ló qua tiêu điểm F′; tia qua tiêu điểm F cho tia ló song song trục chính.","Ảnh qua thấu kính hội tụ: Vật ngoài tiêu cự (d > f) cho ảnh thật, ngược chiều; vật trong tiêu cự (d < f) cho ảnh ảo, cùng chiều, lớn hơn vật."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Kính lúp. Bài tập thấu kính","req":["Nêu được cấu tạo, công dụng của kính lúp; số bội giác; giải bài tập về thấu kính."],"sum":["Kính lúp là thấu kính hội tụ có tiêu cự ngắn, dùng để quan sát vật nhỏ. Vật đặt trong khoảng tiêu cự cho ảnh ảo, cùng chiều, lớn hơn vật.","Khái niệm: Kính lúp là thấu kính hội tụ có tiêu cự ngắn, dùng để quan sát vật nhỏ.","Số bội giác G ghi trên kính (2x, 3x, 5x…): Kính có tiêu cự càng ngắn thì số bội giác càng lớn.","Giải bài tập thấu kính: Vẽ ảnh bằng hai trong ba tia đặc biệt; dùng tam giác đồng dạng hoặc công thức 1/f = 1/d + 1/d′ (ảnh thật) để tìm vị trí, độ lớn ảnh."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương III. Điện","l":[{"t":"Bài 11. Điện trở. Định luật Ohm","req":["Nêu được điện trở; định luật Ohm; công thức tính điện trở của dây dẫn."],"sum":["Điện trở đặc trưng cho mức độ cản trở dòng điện của dây dẫn. Đơn vị điện trở là ôm (Ω);","Điện trở đặc trưng cho mức độ cản trở dòng điện của dây dẫn: Đơn vị điện trở là ôm (Ω);","Cường độ dòng điện chạy qua dây…: Cường độ dòng điện chạy qua dây dẫn tỉ lệ thuận với hiệu điện thế đặt vào hai đầu dây và tỉ lệ nghịch với điện trở của dây.","Điện trở dây dẫn tỉ lệ thuận…: Điện trở dây dẫn tỉ lệ thuận với chiều dài, tỉ lệ nghịch với tiết diện và phụ thuộc vật liệu làm dây."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Đoạn mạch nối tiếp, song song","req":["Tính được cường độ dòng điện, hiệu điện thế, điện trở tương đương trong đoạn mạch nối tiếp, song song."],"m":[{"t":"Tính điện trở và dòng điện trong đoạn mạch","w":"Đề cho các điện trở nối tiếp hoặc song song với hiệu điện thế hay cường độ dòng điện và hỏi điện trở tương đương, I, U.","s":["Xác định cách mắc: nối tiếp (một đường đi) hay song song (rẽ nhánh).","Nối tiếp: R = R₁ + R₂, I giống nhau, U = U₁ + U₂. Song song: 1/R = 1/R₁ + 1/R₂, U giống nhau, I = I₁ + I₂.","Tính R tương đương, rồi I = U/R.","Tính từng điện trở: U₁ = I·R₁ hoặc I₁ = U/R₁; kiểm tra tổng."],"n":["Song song: R tương đương nhỏ hơn mỗi điện trở thành phần.","Hai điện trở bằng nhau mắc song song: R = R₁/2.","Nối tiếp: hiệu điện thế chia theo tỉ lệ điện trở."]}],"sum":["Trong mạch nối tiếp, hiệu điện thế trên mỗi điện trở tỉ lệ thuận với điện trở. Trong mạch song song, cường độ dòng điện qua mỗi nhánh tỉ lệ nghịch với điện trở.","Công thức","Trong mạch nối tiếp, hiệu điện thế…: Trong mạch nối tiếp, hiệu điện thế trên mỗi điện trở tỉ lệ thuận với điện trở."],"d":["Tính điện trở và dòng điện trong đoạn mạch"],"e":["Lưu ý: Song song: R tương đương nhỏ hơn mỗi điện trở thành phần.","Lưu ý: Hai điện trở bằng nhau mắc song song: R = R₁/2.","Lưu ý: Nối tiếp: hiệu điện thế chia theo tỉ lệ điện trở."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 13. Năng lượng của dòng điện và công suất điện","req":["Nêu được năng lượng của dòng điện, công suất điện; tính được điện năng tiêu thụ, công suất."],"m":[{"t":"Tính điện năng tiêu thụ và tiền điện","w":"Đề cho công suất, thời gian dùng của các dụng cụ điện và giá điện, hỏi điện năng (kWh) hoặc tiền điện.","s":["Đổi công suất sang kW và thời gian sang giờ.","Điện năng A = P·t (kWh).","Cộng điện năng của nhiều dụng cụ và nhân số ngày.","Tiền điện = số kWh × giá điện."],"n":["1 kWh = 3 600 000 J.","Đổi W sang kW bằng cách chia cho 1 000.","Dụng cụ khác nhau thì tính riêng rồi cộng."]}],"sum":["Dòng điện có năng lượng vì có thể thực hiện công và cung cấp nhiệt lượng. Năng lượng dòng điện chuyển hoá thành các dạng khác (nhiệt, ánh sáng, cơ năng…).","Khái niệm: Dòng điện có năng lượng vì có thể thực hiện công và cung cấp nhiệt lượng.","Số oát ghi trên dụng cụ điện…: Số oát ghi trên dụng cụ điện cho biết công suất định mức khi dùng đúng hiệu điện thế định mức."],"d":["Tính điện năng tiêu thụ và tiền điện"],"e":["Lưu ý: 1 kWh = 3 600 000 J.","Lưu ý: Đổi W sang kW bằng cách chia cho 1 000.","Lưu ý: Dụng cụ khác nhau thì tính riêng rồi cộng."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4}}}]},{"t":"Chương IV. Điện từ","l":[{"t":"Bài 14. Cảm ứng điện từ. Nguyên tắc tạo ra dòng điện xoay chiều","req":["Nêu được hiện tượng cảm ứng điện từ; điều kiện xuất hiện dòng điện cảm ứng; nguyên tắc tạo dòng điện xoay chiều."],"sum":["Khi số đường sức từ xuyên qua tiết diện cuộn dây dẫn kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng.","Khái niệm: Khi số đường sức từ xuyên qua tiết diện cuộn dây dẫn kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng.","Có thể tạo dòng điện cảm ứng…: Có thể tạo dòng điện cảm ứng bằng cách đưa nam châm lại gần hoặc ra xa cuộn dây, quay nam châm trước cuộn dây, hoặc quay cuộn dây trong từ trường.","Dòng điện xoay chiều là dòng điện luân phiên đổi chiều: Khi cho cuộn dây quay trong từ trường (hoặc nam châm quay trước cuộn dây), số đường sức từ qua cuộn dây luân phiên tăng, giảm nên tạo ra dòng điện…","Dòng điện xoay chiều ở Việt Nam…: Dòng điện xoay chiều ở Việt Nam có tần số 50 Hz (đổi chiều 100 lần mỗi giây)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Tác dụng của dòng điện xoay chiều","req":["Nêu được các tác dụng của dòng điện xoay chiều; an toàn khi sử dụng điện."],"sum":["Dòng điện xoay chiều có các tác dụng: tác dụng nhiệt (bàn là, nồi cơm điện), tác dụng phát sáng (bóng đèn), tác dụng từ (nam châm điện, động cơ điện), tác dụng sinh lí (gây điện giật, ứng dụng trong…","Dòng điện xoay chiều có các tác dụng: Tác dụng nhiệt (bàn là, nồi cơm điện), tác dụng phát sáng (bóng đèn), tác dụng từ (nam châm điện, động cơ điện), tác dụng sinh lí (gây điện giật,…","Tác dụng từ của dòng điện xoay chiều: Lực từ đổi chiều khi dòng điện đổi chiều.","Ampe kế, vôn kế xoay chiều (kí…: Ampe kế, vôn kế xoay chiều (kí hiệu AC hoặc ~) đo giá trị hiệu dụng của cường độ dòng điện, hiệu điện thế xoay chiều.","An toàn điện: Không chạm vào dây điện trần, ổ cắm; dùng thiết bị có vỏ cách điện; lắp cầu chì, aptomat; nối đất cho vỏ kim loại thiết bị."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương V. Năng lượng với cuộc sống","l":[{"t":"Bài 16. Vòng năng lượng trên Trái Đất. Năng lượng hoá thạch","req":["Mô tả sơ lược vòng năng lượng trên Trái Đất; nêu được năng lượng hoá thạch và tác hại khi sử dụng."],"sum":["Hầu hết năng lượng trên Trái Đất có nguồn gốc từ Mặt Trời. Năng lượng Mặt Trời được thực vật hấp thụ qua quang hợp, chuyển cho động vật qua chuỗi thức ăn; tạo ra gió, mưa, dòng chảy; xác sinh vật…","Hầu hết năng lượng trên Trái Đất có nguồn gốc từ Mặt Trời: Năng lượng Mặt Trời được thực vật hấp thụ qua quang hợp, chuyển cho động vật qua chuỗi thức ăn; tạo ra gió, mưa, dòng chảy; xác sinh vật qua hàng…","Nhiên liệu hoá thạch gồm than đá…: Nhiên liệu hoá thạch gồm than đá, dầu mỏ, khí tự nhiên – nguồn năng lượng không tái tạo, đang cạn kiệt.","Đốt nhiên liệu hoá thạch thải ra…: Đốt nhiên liệu hoá thạch thải ra khí CO₂ (gây hiệu ứng nhà kính, biến đổi khí hậu), SO₂, NO₂ (gây mưa acid), bụi mịn (gây bệnh hô hấp).","Giải pháp: Tiết kiệm năng lượng, sử dụng năng lượng tái tạo, nâng cao hiệu suất thiết bị."],"e":["Hay nhầm: Một phần nhỏ (địa nhiệt).","Hay nhầm: Gió có nguồn gốc từ Mặt Trời."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Một số dạng năng lượng tái tạo","req":["Nêu được một số dạng năng lượng tái tạo; ưu, nhược điểm; ứng dụng ở Việt Nam."],"sum":["Năng lượng tái tạo gồm: năng lượng Mặt Trời (pin mặt trời, máy nước nóng), năng lượng gió (tuabin gió), năng lượng nước (thuỷ điện, thuỷ triều, sóng biển), năng lượng địa nhiệt, năng lượng sinh khối…","Năng lượng tái tạo gồm: Năng lượng Mặt Trời (pin mặt trời, máy nước nóng), năng lượng gió (tuabin gió), năng lượng nước (thuỷ điện, thuỷ triều, sóng biển), năng lượng địa…","Ưu điểm: Gần như vô hạn, ít phát thải khí nhà kính.","Việt Nam có tiềm năng lớn về…: Việt Nam có tiềm năng lớn về điện mặt trời (Nam Trung Bộ, Tây Nguyên), điện gió (ven biển), thuỷ điện (Hoà Bình, Sơn La, Lai Châu)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Mở đầu","l":[{"t":"Bài tập nâng cao · Mở đầu (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chương I. Năng lượng cơ học","l":[{"t":"Bài tập nâng cao · Chương I. Năng lượng cơ học (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương II. Ánh sáng","l":[{"t":"Bài tập nâng cao · Chương II. Ánh sáng (10 câu)","e":["Hay nhầm: Kính lọc chỉ cho xanh lam đi qua."],"q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương III. Điện","l":[{"t":"Bài tập nâng cao · Chương III. Điện (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương IV. Điện từ","l":[{"t":"Bài tập nâng cao · Chương IV. Điện từ (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương V. Năng lượng với cuộc sống","l":[{"t":"Bài tập nâng cao · Chương V. Năng lượng với cuộc sống (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 9","c":[{"t":"Chương VI. Kim loại. Sự khác nhau cơ bản giữa phi kim và kim loại","l":[{"t":"Bài 18. Tính chất chung của kim loại","req":["Nêu được tính chất vật lí, tính chất hoá học chung của kim loại; viết phương trình hoá học minh hoạ."],"sum":["Tính chất vật lí: kim loại có tính dẻo, tính dẫn điện, dẫn nhiệt, có ánh kim. Dẫn điện tốt nhất là Ag, sau đó Cu, Au, Al, Fe.","Tính chất vật lí: Kim loại có tính dẻo, tính dẫn điện, dẫn nhiệt, có ánh kim.","Tác dụng với phi kim: Với oxygen tạo oxide (3Fe + 2O₂ → Fe₃O₄); với chlorine tạo muối chloride (2Na + Cl₂ → 2NaCl); với sulfur tạo muối sulfide (Fe + S → FeS).","Tác dụng với nước: Kim loại mạnh như Na, K, Ca phản ứng ở nhiệt độ thường tạo base và khí hydrogen: 2Na + 2H₂O → 2NaOH + H₂.","Tác dụng với dung dịch acid (HCl, H₂SO₄ loãng): Nhiều kim loại tạo muối và giải phóng H₂: Fe + 2HCl → FeCl₂ + H₂."],"e":["Hay nhầm: Ag không phản ứng với HCl.","Hay nhầm: Cu không phản ứng với HCl."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Dãy hoạt động hoá học","req":["Nêu được dãy hoạt động hoá học của một số kim loại và ý nghĩa."],"sum":["Dãy hoạt động hoá học của một số kim loại: K, Na, Ca, Mg, Al, Zn, Fe, Pb, (H), Cu, Ag, Au.","Dãy hoạt động hoá học của một số kim loại: K, Na, Ca, Mg, Al, Zn, Fe, Pb, (H), Cu, Ag, Au.","Ý nghĩa: K, Na, Ca phản ứng với nước ở nhiệt độ thường tạo base và H₂.","Kim loại đứng sau H (Cu, Ag…: Kim loại đứng sau H (Cu, Ag, Au) không phản ứng với HCl, H₂SO₄ loãng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 20. Tách kim loại và việc sử dụng hợp kim","req":["Nêu được phương pháp tách kim loại; quá trình sản xuất gang, thép, nhôm; khái niệm, ứng dụng hợp kim."],"sum":["Phương pháp tách kim loại phụ thuộc mức độ hoạt động: điện phân nóng chảy với kim loại mạnh (Na, Mg, Al); dùng chất khử (C, CO, H₂) ở nhiệt độ cao với kim loại trung bình (Zn, Fe, Pb, Cu); kim loại…","Phương pháp tách kim loại phụ thuộc mức độ hoạt động: Điện phân nóng chảy với kim loại mạnh (Na, Mg, Al); dùng chất khử (C, CO, H₂) ở nhiệt độ cao với kim loại trung bình (Zn, Fe, Pb, Cu); kim loại yếu…","Sản xuất gang: Khử oxide sắt bằng CO trong lò cao: Fe₂O₃ + 3CO → 2Fe + 3CO₂.","Hợp kim là vật liệu kim loại…: Hợp kim là vật liệu kim loại có chứa một kim loại cơ bản và một số kim loại hoặc phi kim khác.","Hợp kim thường cứng hơn, bền hơn…: Hợp kim thường cứng hơn, bền hơn kim loại thành phần, ít bị ăn mòn hơn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 21. Sự khác nhau cơ bản giữa phi kim và kim loại","req":["Nêu được sự khác nhau cơ bản về tính chất vật lí và hoá học giữa phi kim và kim loại."],"sum":["Tính chất vật lí: kim loại thường ở thể rắn (trừ Hg), có ánh kim, dẫn điện, dẫn nhiệt tốt, dẻo.","Tính chất vật lí: Kim loại thường ở thể rắn (trừ Hg), có ánh kim, dẫn điện, dẫn nhiệt tốt, dẻo.","Tính chất hoá học: Kim loại dễ nhường electron tạo ion dương; oxide của kim loại thường là oxide base (CaO, Na₂O).","Kim loại phản ứng với phi kim…: Kim loại phản ứng với phi kim tạo muối hoặc oxide; phi kim phản ứng với hydrogen tạo hợp chất khí (HCl, H₂S)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VII. Giới thiệu về chất hữu cơ","l":[{"t":"Bài 22. Giới thiệu về hợp chất hữu cơ","req":["Nêu được khái niệm hợp chất hữu cơ, hoá học hữu cơ; công thức phân tử, công thức cấu tạo; phân loại hydrocarbon và dẫn xuất."],"sum":["Hợp chất hữu cơ là hợp chất của carbon (trừ CO, CO₂, H₂CO₃, muối carbonate, carbide…). Hoá học hữu cơ là ngành hoá học nghiên cứu các hợp chất hữu cơ.","Khái niệm: Hợp chất hữu cơ là hợp chất của carbon (trừ CO, CO₂, H₂CO₃, muối carbonate, carbide…).","Đặc điểm: Thường có liên kết cộng hoá trị; dễ cháy; kém bền nhiệt; thường khó tan trong nước.","Phân loại: Hydrocarbon (chỉ chứa C và H: CH₄, C₂H₄) và dẫn xuất của hydrocarbon (ngoài C, H còn có O, N, Cl…: C₂H₅OH, CH₃COOH).","Trong hợp chất hữu cơ, C có…: Trong hợp chất hữu cơ, C có hoá trị IV, H hoá trị I, O hoá trị II."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 23. Alkane","req":["Nêu được khái niệm alkane, công thức chung; tính chất vật lí, hoá học (phản ứng cháy); ứng dụng."],"sum":["Alkane là hydrocarbon mạch hở chỉ chứa liên kết đơn. Công thức chung CₙH₂ₙ₊₂ (n ≥ 1).","Alkane là hydrocarbon mạch hở chỉ chứa liên kết đơn: Công thức chung CₙH₂ₙ₊₂ (n ≥ 1).","Ở điều kiện thường, alkane từ C₁…: Ở điều kiện thường, alkane từ C₁ đến C₄ ở thể khí; không tan trong nước, nhẹ hơn nước.","Phản ứng cháy toả nhiều nhiệt: CH₄ + 2O₂ → CO₂ + 2H₂O.","Khi đốt cháy thiếu oxygen sinh ra…: Khi đốt cháy thiếu oxygen sinh ra CO độc; cần sử dụng gas an toàn, thông gió."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 24. Alkene","req":["Nêu được khái niệm alkene; cấu tạo, tính chất của ethylene; ứng dụng."],"sum":["Alkene là hydrocarbon mạch hở có một liên kết đôi C=C. Công thức chung CₙH₂ₙ (n ≥ 2).","Alkene là hydrocarbon mạch hở có một liên kết đôi C=C: Công thức chung CₙH₂ₙ (n ≥ 2).","Ethylene là chất khí không màu, không…: Ethylene là chất khí không màu, không mùi, ít tan trong nước.","Tính chất hoá học: Phản ứng cháy (C₂H₄ + 3O₂ → 2CO₂ + 2H₂O); phản ứng cộng làm mất màu nước bromine (C₂H₄ + Br₂ → C₂H₄Br₂); phản ứng trùng hợp tạo polyethylene (PE).","Ứng dụng: Sản xuất PE, ethylic alcohol, kích thích quả mau chín."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 25. Nguồn nhiên liệu","req":["Nêu được khái niệm nhiên liệu, phân loại; dầu mỏ, khí thiên nhiên; sử dụng nhiên liệu hiệu quả, an toàn."],"sum":["Nhiên liệu là chất cháy được, khi cháy toả nhiệt và phát sáng, dùng làm nguồn năng lượng. Phân loại: rắn (than, gỗ), lỏng (xăng, dầu), khí (khí thiên nhiên, khí mỏ dầu, biogas).","Khái niệm: Nhiên liệu là chất cháy được, khi cháy toả nhiệt và phát sáng, dùng làm nguồn năng lượng.","Dầu mỏ là hỗn hợp nhiều hydrocarbon…: Dầu mỏ là hỗn hợp nhiều hydrocarbon; qua chưng cất tách được khí, xăng, dầu hoả, dầu diesel, dầu mazut, nhựa đường.","Sử dụng nhiên liệu hiệu quả: Cung cấp đủ không khí, tăng diện tích tiếp xúc, điều chỉnh lượng nhiên liệu; nhiên liệu hoá thạch gây ô nhiễm cần sử dụng tiết kiệm, phát triển…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VIII. Ethylic alcohol và acetic acid","l":[{"t":"Bài 26. Ethylic alcohol","req":["Nêu được công thức, tính chất vật lí, hoá học của ethylic alcohol; độ cồn; ứng dụng và tác hại của rượu bia."],"sum":["Ethylic alcohol (ethanol) có công thức C₂H₅OH (CH₃–CH₂–OH), là chất lỏng không màu, sôi ở 78,3 °C, nhẹ hơn nước, tan vô hạn trong nước, hoà tan được nhiều chất.","Khái niệm: Ethylic alcohol (ethanol) có công thức C₂H₅OH (CH₃–CH₂–OH), là chất lỏng không màu, sôi ở 78,3 °C, nhẹ hơn nước, tan vô hạn trong nước, hoà tan được…","Độ cồn là số mL ethylic alcohol…: Độ cồn là số mL ethylic alcohol nguyên chất có trong 100 mL hỗn hợp với nước.","Tính chất hoá học: Cháy với ngọn lửa xanh (C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O); tác dụng với sodium giải phóng H₂ (2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂).","Ứng dụng: Nhiên liệu, dung môi, sát trùng (cồn 70°), sản xuất acetic acid."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 27. Acetic acid","req":["Nêu được công thức, tính chất vật lí, hoá học của acetic acid; ứng dụng; phản ứng ester hoá."],"sum":["Acetic acid có công thức CH₃COOH, là chất lỏng không màu, vị chua, tan vô hạn trong nước. Giấm ăn là dung dịch acetic acid 2–5%.","Khái niệm: Acetic acid có công thức CH₃COOH, là chất lỏng không màu, vị chua, tan vô hạn trong nước.","Tính chất hoá học: Là acid yếu, làm quỳ tím hoá đỏ; tác dụng với kim loại (đứng trước H) giải phóng H₂; tác dụng với base, oxide base, muối carbonate: CH₃COOH + NaOH →…","Phản ứng ester hoá với ethylic alcohol (xúc tác H₂SO₄ đặc, đun nóng): CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O (ethyl acetate).","Ứng dụng: Làm giấm ăn, sản xuất tơ nhân tạo, dược phẩm, chất dẻo, thuốc diệt cỏ."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương IX. Lipid. Carbohydrate. Protein. Polymer","l":[{"t":"Bài 28. Lipid","req":["Nêu được khái niệm lipid, chất béo; tính chất vật lí, hoá học (phản ứng thuỷ phân); vai trò."],"sum":["Lipid là những hợp chất hữu cơ có trong tế bào sống, không tan trong nước, tan trong dung môi hữu cơ.","Khái niệm: Lipid là những hợp chất hữu cơ có trong tế bào sống, không tan trong nước, tan trong dung môi hữu cơ.","Tính chất vật lí: Chất béo nhẹ hơn nước, không tan trong nước.","Phản ứng thuỷ phân trong môi trường kiềm (phản ứng xà phòng hoá): Chất béo + NaOH → glycerol + muối của acid béo (xà phòng).","Vai trò: Cung cấp và dự trữ năng lượng (1 g chất béo cho khoảng 38 kJ), hoà tan vitamin A, D, E, K; dùng sản xuất xà phòng, glycerol."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 29. Carbohydrate. Glucose và saccharose","req":["Nêu được khái niệm carbohydrate; công thức, tính chất, ứng dụng của glucose và saccharose."],"sum":["Carbohydrate là hợp chất hữu cơ tạp chức, thường có công thức chung Cₙ(H₂O)ₘ. Gồm glucose, saccharose, tinh bột, cellulose…","Khái niệm: Carbohydrate là hợp chất hữu cơ tạp chức, thường có công thức chung Cₙ(H₂O)ₘ.","Glucose C₆H₁₂O₆: Chất rắn kết tinh, không màu, vị ngọt, dễ tan trong nước; có nhiều trong quả chín (đặc biệt nho).","Saccharose C₁₂H₂₂O₁₁: Có trong mía, củ cải đường, thốt nốt; thuỷ phân (acid hoặc enzyme) tạo glucose và fructose.","Ứng dụng: Glucose làm thuốc tăng lực, truyền dịch, tráng gương; saccharose làm thực phẩm, bánh kẹo, pha chế thuốc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 30. Tinh bột và cellulose","req":["Nêu được trạng thái tự nhiên, tính chất, ứng dụng của tinh bột và cellulose; sự tạo thành trong cây xanh."],"sum":["Tinh bột và cellulose có công thức chung (C₆H₁₀O₅)ₙ, là polymer thiên nhiên. Tinh bột có nhiều trong hạt, củ, quả (gạo, ngô, khoai, sắn); cellulose là thành phần chính của thành tế bào thực vật…","Khái niệm: Tinh bột và cellulose có công thức chung (C₆H₁₀O₅)ₙ, là polymer thiên nhiên.","Tinh bột là chất rắn màu trắng…: Tinh bột là chất rắn màu trắng, không tan trong nước lạnh, tan trong nước nóng tạo hồ tinh bột.","Thuỷ phân tinh bột hoặc cellulose (xúc…: Thuỷ phân tinh bột hoặc cellulose (xúc tác acid, đun nóng) tạo glucose.","Trong cây xanh, tinh bột và cellulose được tạo thành nhờ quang hợp: 6nCO₂ + 5nH₂O → (C₆H₁₀O₅)ₙ + 6nO₂ (ánh sáng, diệp lục)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 31. Protein","req":["Nêu được khái niệm, cấu tạo, tính chất của protein; vai trò."],"sum":["Protein là hợp chất hữu cơ phức tạp, phân tử khối lớn, được tạo thành từ nhiều amino acid liên kết với nhau.","Khái niệm: Protein là hợp chất hữu cơ phức tạp, phân tử khối lớn, được tạo thành từ nhiều amino acid liên kết với nhau.","Protein có trong cơ thể người, động…: Protein có trong cơ thể người, động vật, thực vật (thịt, cá, trứng, sữa, đậu).","Tính chất: Thuỷ phân (acid, base hoặc enzyme) tạo các amino acid; bị đông tụ khi đun nóng hoặc gặp acid, base, muối kim loại nặng; khi cháy có mùi khét.","Vai trò: Thành phần cấu tạo tế bào; enzyme, hormone, kháng thể; nguồn dinh dưỡng thiết yếu."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 32. Polymer","req":["Nêu được khái niệm polymer, phân loại; ứng dụng (chất dẻo, tơ, cao su); sử dụng an toàn, bảo vệ môi trường."],"sum":["Polymer là những chất có phân tử khối rất lớn, do nhiều mắt xích liên kết với nhau. Ví dụ polyethylene (–CH₂–CH₂–)ₙ.","Khái niệm: Polymer là những chất có phân tử khối rất lớn, do nhiều mắt xích liên kết với nhau.","Phân loại: Polymer thiên nhiên (tinh bột, cellulose, protein, cao su thiên nhiên) và polymer tổng hợp (PE, PVC, nylon, cao su buna).","Polymer thường là chất rắn, không bay…: Polymer thường là chất rắn, không bay hơi, không tan trong nước.","Rác thải polymer khó phân huỷ gây…: Rác thải polymer khó phân huỷ gây ô nhiễm; cần giảm dùng đồ nhựa một lần, tái chế, phân loại rác."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương X. Khai thác tài nguyên từ vỏ Trái Đất","l":[{"t":"Bài 33. Sơ lược về hoá học vỏ Trái Đất và khai thác tài nguyên từ vỏ Trái Đất","req":["Nêu được thành phần hoá học của vỏ Trái Đất; tài nguyên và khai thác hợp lí."],"sum":["Vỏ Trái Đất chứa nhiều nguyên tố, phổ biến nhất là oxygen (khoảng 46%), silicon (khoảng 28%), sau đó nhôm, sắt, calcium, sodium, potassium, magnesium.","Khái niệm: Vỏ Trái Đất chứa nhiều nguyên tố, phổ biến nhất là oxygen (khoảng 46%), silicon (khoảng 28%), sau đó nhôm, sắt, calcium, sodium, potassium, magnesium.","Tài nguyên từ vỏ Trái Đất: Khoáng sản kim loại (sắt, nhôm, đồng), phi kim (đá vôi, cát, đất sét), nhiên liệu hoá thạch (than, dầu mỏ, khí thiên nhiên).","Khai thác tài nguyên cần hợp lí…: Khai thác tài nguyên cần hợp lí, tiết kiệm, kết hợp tái chế; hạn chế ô nhiễm, suy thoái môi trường; tuân thủ luật khoáng sản."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 34. Khai thác đá vôi. Công nghiệp silicate","req":["Nêu được thành phần, ứng dụng của đá vôi; quá trình sản xuất vôi, xi măng, gốm sứ, thuỷ tinh."],"sum":["Đá vôi có thành phần chính là CaCO₃. Nung đá vôi ở nhiệt độ cao: CaCO₃ → CaO + CO₂ (vôi sống).","Đá vôi có thành phần chính là CaCO₃: Nung đá vôi ở nhiệt độ cao: CaCO₃ → CaO + CO₂ (vôi sống).","Ứng dụng đá vôi: Sản xuất vôi, xi măng, làm vật liệu xây dựng, chất phụ gia, khử chua đất.","Công nghiệp silicate sản xuất đồ gốm…: Công nghiệp silicate sản xuất đồ gốm, sứ, xi măng, thuỷ tinh từ các hợp chất tự nhiên của silicon.","Khai thác đá vôi cần bảo vệ…: Khai thác đá vôi cần bảo vệ cảnh quan, hạn chế bụi và khí thải CO₂."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 35. Khai thác nhiên liệu hoá thạch. Nguồn carbon. Chu trình carbon và sự ấm lên toàn cầu","req":["Nêu được khai thác nhiên liệu hoá thạch; nguồn carbon; chu trình carbon; khí nhà kính và sự ấm lên toàn cầu."],"sum":["Nhiên liệu hoá thạch (than, dầu mỏ, khí thiên nhiên) được khai thác bằng khai mỏ (lộ thiên, hầm lò) hoặc khoan giếng.","Khái niệm: Nhiên liệu hoá thạch (than, dầu mỏ, khí thiên nhiên) được khai thác bằng khai mỏ (lộ thiên, hầm lò) hoặc khoan giếng.","Carbon có trong khí quyển (CO₂), sinh…: Carbon có trong khí quyển (CO₂), sinh vật, đất, đại dương, đá vôi và nhiên liệu hoá thạch.","Chu trình carbon: Thực vật hấp thụ CO₂ qua quang hợp; sinh vật thải CO₂ qua hô hấp; phân giải xác sinh vật trả lại CO₂;","Khí nhà kính (CO₂, CH₄, hơi nước…)…: Khí nhà kính (CO₂, CH₄, hơi nước…) giữ nhiệt làm Trái Đất ấm lên."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương VI. Kim loại. Sự khác nhau cơ bản giữa phi kim và kim loại","l":[{"t":"Bài tập nâng cao · Chương VI. Kim loại. Sự khác nhau cơ bản giữa phi kim và kim loại (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương VII. Giới thiệu về chất hữu cơ","l":[{"t":"Bài tập nâng cao · Chương VII. Giới thiệu về chất hữu cơ (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương VIII. Ethylic alcohol và acetic acid","l":[{"t":"Bài tập nâng cao · Chương VIII. Ethylic alcohol và acetic acid (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương IX. Lipid. Carbohydrate. Protein. Polymer","l":[{"t":"Bài tập nâng cao · Chương IX. Lipid. Carbohydrate. Protein. Polymer (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương X. Khai thác tài nguyên từ vỏ Trái Đất","l":[{"t":"Bài tập nâng cao · Chương X. Khai thác tài nguyên từ vỏ Trái Đất (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 9","c":[{"t":"Chương XI. Di truyền học Mendel. Cơ sở phân tử của hiện tượng di truyền","l":[{"t":"Bài 36. Khái quát về di truyền học","req":["Nêu được khái niệm di truyền, biến dị; một số thuật ngữ, kí hiệu cơ bản của di truyền học."],"sum":["Di truyền là hiện tượng truyền đạt các đặc điểm của bố mẹ, tổ tiên cho các thế hệ con cháu.","Khái niệm: Di truyền là hiện tượng truyền đạt các đặc điểm của bố mẹ, tổ tiên cho các thế hệ con cháu.","Một số thuật ngữ: Tính trạng (đặc điểm về hình thái, cấu tạo, sinh lí); cặp tính trạng tương phản (hai trạng thái biểu hiện trái ngược của cùng loại tính trạng); nhân…","Kí hiệu: P (bố mẹ), F₁, F₂ (thế hệ con), G (giao tử), × (phép lai), ♀ (cái), ♂ (đực).","Mendel dùng phương pháp phân tích các thế hệ lai: Lai các cặp bố mẹ thuần chủng khác nhau về một hoặc vài cặp tính trạng tương phản, theo dõi sự di truyền ở con cháu, dùng toán thống kê phân tích."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 37. Các quy luật di truyền của Mendel","req":["Trình bày được thí nghiệm lai một cặp, hai cặp tính trạng của Mendel; quy luật phân li, phân li độc lập; phép lai phân tích."],"m":[{"t":"Giải bài tập lai một cặp tính trạng","w":"Đề cho kiểu hình P, F₁ hoặc F₂ và hỏi kiểu gene, kiểu hình, tỉ lệ, số cá thể.","s":["Xác định tính trạng trội, lặn dựa vào F₁ (đồng tính) hoặc tỉ lệ 3 : 1.","Quy ước gene: A trội, a lặn.","Viết sơ đồ lai: P → giao tử → F₁ → F₂ (lập bảng Punnett nếu cần).","Tính tỉ lệ kiểu gene, kiểu hình; tính số cá thể = tỉ lệ × tổng số."],"n":["Aa × Aa cho F₁ tỉ lệ kiểu gene 1 AA : 2 Aa : 1 aa, kiểu hình 3 : 1.","Phép lai phân tích dùng cá thể mang tính trạng lặn.","Trong 3 trội có 1/3 đồng hợp, 2/3 dị hợp."]}],"sum":["Lai một cặp tính trạng: P thuần chủng hoa tím × hoa trắng → F₁ 100% hoa tím; F₁ tự thụ phấn → F₂ tỉ lệ 3 tím : 1 trắng.","Lai một cặp tính trạng: P thuần chủng hoa tím × hoa trắng → F₁ 100% hoa tím;","Quy luật phân li: Mỗi tính trạng do một cặp nhân tố di truyền quy định; trong quá trình phát sinh giao tử, mỗi nhân tố di truyền trong cặp phân li về một giao tử.","Lai hai cặp tính trạng: P vàng, trơn × xanh, nhăn (thuần chủng) → F₁ 100% vàng, trơn;","Phép lai phân tích: Lai cá thể mang tính trạng trội cần xác định kiểu gene với cá thể mang tính trạng lặn."],"d":["Giải bài tập lai một cặp tính trạng"],"e":["Lưu ý: Aa × Aa cho F₁ tỉ lệ kiểu gene 1 AA : 2 Aa : 1 aa, kiểu hình 3 : 1.","Lưu ý: Phép lai phân tích dùng cá thể mang tính trạng lặn.","Lưu ý: Trong 3 trội có 1/3 đồng hợp, 2/3 dị hợp."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 38. Nucleic acid và gene","req":["Nêu được thành phần hoá học, cấu trúc DNA, RNA; khái niệm gene."],"m":[{"t":"Tính toán số nucleotide, chiều dài và liên kết hydrogen của DNA","w":"Đề cho số nucleotide từng loại hoặc phần trăm, hỏi số nucleotide còn lại, chiều dài, số liên kết H.","s":["Dùng nguyên tắc bổ sung: A = T, G = C.","Tổng số nucleotide N = 2A + 2G (hay A + G = N/2).","Chiều dài L = (N/2)·0,34 nm.","Số liên kết hydrogen H = 2A + 3G."],"n":["Số nucleotide tính cho cả hai mạch.","A + G luôn bằng N/2.","%A + %G = 50%."]}],"sum":["Nucleic acid gồm DNA và RNA, là đại phân tử được cấu tạo theo nguyên tắc đa phân, đơn phân là nucleotide.","Khái niệm: Nucleic acid gồm DNA và RNA, là đại phân tử được cấu tạo theo nguyên tắc đa phân, đơn phân là nucleotide.","DNA gồm hai mạch polynucleotide xoắn kép…: DNA gồm hai mạch polynucleotide xoắn kép; bốn loại nucleotide A, T, G, C.","RNA gồm một mạch, đơn phân A, U, G, C; có mRNA, tRNA, rRNA: Gene là một đoạn DNA mang thông tin quy định một sản phẩm nhất định (RNA hoặc protein)."],"d":["Tính toán số nucleotide, chiều dài và liên kết hydrogen của DNA"],"e":["Lưu ý: Số nucleotide tính cho cả hai mạch.","Lưu ý: A + G luôn bằng N/2.","Lưu ý: %A + %G = 50%."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 39. Tái bản DNA và phiên mã tạo RNA","req":["Mô tả quá trình tái bản DNA, phiên mã; ý nghĩa của nguyên tắc bổ sung."],"sum":["Tái bản DNA là quá trình tạo ra phân tử DNA mới từ DNA ban đầu, diễn ra trong nhân tế bào.","Khái niệm: Tái bản DNA là quá trình tạo ra phân tử DNA mới từ DNA ban đầu, diễn ra trong nhân tế bào.","Phiên mã là quá trình tổng hợp…: Phiên mã là quá trình tổng hợp RNA từ mạch khuôn của gene theo nguyên tắc bổ sung: A–U, T–A, G–C, C–G.","Nguyên tắc bổ sung giúp thông tin…: Nguyên tắc bổ sung giúp thông tin di truyền được truyền đạt chính xác qua các thế hệ tế bào và cơ thể."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 40. Dịch mã và mối quan hệ từ gene đến tính trạng","req":["Mô tả quá trình dịch mã; mã di truyền; mối quan hệ gene – mRNA – protein – tính trạng."],"sum":["Dịch mã là quá trình tổng hợp chuỗi polypeptide (protein) từ mRNA, diễn ra ở ribosome trong tế bào chất. tRNA vận chuyển amino acid, đối mã (anticodon) khớp với mã bộ ba (codon) trên mRNA theo…","Khái niệm: Dịch mã là quá trình tổng hợp chuỗi polypeptide (protein) từ mRNA, diễn ra ở ribosome trong tế bào chất. tRNA vận chuyển amino acid, đối mã…","Mã di truyền là mã bộ ba: Ba nucleotide liên tiếp trên mRNA mã hoá một amino acid.","Số amino acid trong chuỗi polypeptide hoàn…: Số amino acid trong chuỗi polypeptide hoàn chỉnh = (số nucleotide mRNA : 3) − 2 (bỏ bộ ba kết thúc và amino acid mở đầu)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 41. Đột biến gene","req":["Nêu được khái niệm đột biến gene, các dạng; nguyên nhân; vai trò và tác hại."],"sum":["Đột biến gene là những biến đổi trong cấu trúc của gene, thường liên quan đến một hoặc một số cặp nucleotide.","Khái niệm: Đột biến gene là những biến đổi trong cấu trúc của gene, thường liên quan đến một hoặc một số cặp nucleotide.","Nguyên nhân: Tác nhân vật lí (tia phóng xạ, tia UV), hoá học (chất độc hoá học), sinh học (virus) hoặc rối loạn trong quá trình tái bản DNA.","Đột biến gene có thể có hại…: Đột biến gene có thể có hại (gây bệnh hồng cầu hình liềm, bạch tạng), có lợi hoặc trung tính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương XII. Di truyền nhiễm sắc thể","l":[{"t":"Bài 42. Nhiễm sắc thể và bộ nhiễm sắc thể","req":["Nêu được khái niệm, cấu trúc nhiễm sắc thể; bộ nhiễm sắc thể lưỡng bội, đơn bội; tính đặc trưng."],"sum":["Nhiễm sắc thể (NST) là cấu trúc mang gene, nằm trong nhân tế bào, gồm DNA và protein histone.","Khái niệm: Nhiễm sắc thể (NST) là cấu trúc mang gene, nằm trong nhân tế bào, gồm DNA và protein histone.","Trong tế bào sinh dưỡng, NST tồn…: Trong tế bào sinh dưỡng, NST tồn tại thành từng cặp tương đồng (giống nhau về hình thái, kích thước): bộ NST lưỡng bội 2n.","Mỗi loài có bộ NST đặc trưng…: Mỗi loài có bộ NST đặc trưng về số lượng, hình dạng, cấu trúc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 43. Nguyên phân và giảm phân","req":["Trình bày được quá trình nguyên phân, giảm phân; ý nghĩa; mối quan hệ giữa giảm phân và thụ tinh."],"m":[{"t":"Tính số tế bào và NST qua nguyên phân, giảm phân","w":"Đề cho số tế bào ban đầu, số lần nguyên phân, bộ NST 2n và hỏi số tế bào con, số NST, số giao tử.","s":["Nguyên phân k lần từ a tế bào: số tế bào con = a·2ᵏ.","Số NST đơn trong các tế bào con = a·2ᵏ·2n.","Giảm phân: 1 tế bào sinh tinh → 4 tinh trùng; 1 tế bào sinh trứng → 1 trứng.","Tính từng bước và kiểm tra bằng bộ NST n hoặc 2n của loại tế bào đang xét."],"n":["Giảm phân tạo tế bào đơn bội n; nguyên phân giữ nguyên 2n.","Lũy thừa: 2⁴ = 16, không phải 8.","Tế bào sinh trứng chỉ cho 1 trứng."]}],"sum":["Nguyên phân là hình thức phân chia tế bào, từ một tế bào mẹ (2n) tạo hai tế bào con có bộ NST giống hệt tế bào mẹ (2n).","Khái niệm: Nguyên phân là hình thức phân chia tế bào, từ một tế bào mẹ (2n) tạo hai tế bào con có bộ NST giống hệt tế bào mẹ (2n).","Giảm phân xảy ra ở tế bào…: Giảm phân xảy ra ở tế bào sinh dục chín, gồm hai lần phân bào liên tiếp nhưng NST chỉ nhân đôi một lần, tạo bốn tế bào con có bộ NST đơn bội (n).","Thụ tinh là sự kết hợp giữa…: Thụ tinh là sự kết hợp giữa giao tử đực (n) và giao tử cái (n) tạo hợp tử (2n)."],"d":["Tính số tế bào và NST qua nguyên phân, giảm phân"],"e":["Lưu ý: Giảm phân tạo tế bào đơn bội n; nguyên phân giữ nguyên 2n.","Lưu ý: Lũy thừa: 2⁴ = 16, không phải 8.","Lưu ý: Tế bào sinh trứng chỉ cho 1 trứng."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4}}},{"t":"Bài 44. Nhiễm sắc thể giới tính và cơ chế xác định giới tính","req":["Phân biệt NST thường và NST giới tính; cơ chế xác định giới tính; các yếu tố ảnh hưởng."],"sum":["Trong tế bào lưỡng bội có các cặp NST thường và một cặp NST giới tính. Ở người: nữ XX, nam XY.","Khái niệm: Trong tế bào lưỡng bội có các cặp NST thường và một cặp NST giới tính.","Cơ chế xác định giới tính ở người: Mẹ (XX) cho một loại trứng X; bố (XY) cho hai loại tinh trùng X và Y với tỉ lệ ngang nhau.","Giới tính còn chịu ảnh hưởng của môi trường trong và ngoài: Hormone sinh dục, nhiệt độ (một số loài bò sát), ánh sáng… Ứng dụng: điều chỉnh tỉ lệ đực cái trong chăn nuôi."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 45. Di truyền liên kết","req":["Nêu được thí nghiệm của Morgan; khái niệm di truyền liên kết; ý nghĩa."],"sum":["Morgan lai ruồi giấm thân xám, cánh dài thuần chủng với thân đen, cánh cụt → F₁ 100% thân xám, cánh dài.","Khái niệm: Morgan lai ruồi giấm thân xám, cánh dài thuần chủng với thân đen, cánh cụt → F₁ 100% thân xám, cánh dài.","Di truyền liên kết là hiện tượng…: Di truyền liên kết là hiện tượng một nhóm tính trạng được di truyền cùng nhau, do các gene quy định chúng cùng nằm trên một NST, cùng phân li trong…","Số nhóm gene liên kết bằng số NST trong bộ đơn bội (n): Ý nghĩa: hạn chế biến dị tổ hợp, đảm bảo sự di truyền bền vững của từng nhóm tính trạng; trong chọn giống có thể chọn được nhóm tính trạng tốt đi…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 46. Đột biến nhiễm sắc thể","req":["Nêu được khái niệm, các dạng đột biến cấu trúc và số lượng NST; hậu quả, vai trò."],"sum":["Đột biến NST là những biến đổi về cấu trúc hoặc số lượng NST.","Khái niệm: Đột biến NST là những biến đổi về cấu trúc hoặc số lượng NST.","Đột biến cấu trúc NST: Mất đoạn, lặp đoạn, đảo đoạn, chuyển đoạn.","Đột biến số lượng NST: Lệch bội (thêm hoặc mất một hay vài NST ở một cặp, ví dụ thể ba nhiễm 2n + 1, thể một nhiễm 2n − 1);","Hội chứng Down: Có 3 NST số 21 (2n + 1 = 47)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương XIII. Di truyền học với con người và đời sống","l":[{"t":"Bài 47. Di truyền học với con người","req":["Nêu được một số bệnh, tật di truyền ở người; ý nghĩa của di truyền học trong hôn nhân và tư vấn di truyền."],"sum":["Một số bệnh, tật di truyền: hội chứng Down (3 NST số 21), hội chứng Turner (XO, nữ có một NST X), bệnh bạch tạng (đột biến gene lặn), bệnh mù màu và máu khó đông (gene lặn trên NST X), tật hở khe…","Một số bệnh, tật di truyền: Hội chứng Down (3 NST số 21), hội chứng Turner (XO, nữ có một NST X), bệnh bạch tạng (đột biến gene lặn), bệnh mù màu và máu khó đông (gene lặn trên…","Nguyên nhân: Tác nhân vật lí, hoá học trong môi trường (phóng xạ, chất độc da cam, thuốc trừ sâu), rối loạn trao đổi chất nội bào, kết hôn gần.","Luật Hôn nhân và Gia đình cấm…: Luật Hôn nhân và Gia đình cấm kết hôn giữa những người có quan hệ huyết thống trong phạm vi ba đời vì làm tăng khả năng xuất hiện bệnh di truyền do…","Tư vấn di truyền giúp dự đoán…: Tư vấn di truyền giúp dự đoán khả năng xuất hiện bệnh di truyền ở đời con, đưa ra lời khuyên trong hôn nhân, sinh đẻ."],"e":["Hay nhầm: Gene lặn trên NST thường."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 48. Ứng dụng công nghệ di truyền vào đời sống","req":["Nêu được khái niệm công nghệ di truyền; ứng dụng trong nông nghiệp, y học, pháp y, bảo vệ môi trường; vấn đề đạo đức sinh học."],"sum":["Công nghệ di truyền là quy trình kĩ thuật dựa trên các nguyên lí di truyền để tạo ra sinh vật mang đặc điểm mới hoặc sản phẩm có giá trị.","Khái niệm: Công nghệ di truyền là quy trình kĩ thuật dựa trên các nguyên lí di truyền để tạo ra sinh vật mang đặc điểm mới hoặc sản phẩm có giá trị.","Nông nghiệp: Tạo giống cây trồng biến đổi gene (lúa vàng giàu tiền vitamin A, ngô kháng sâu), vật nuôi năng suất cao.","Y học: Sản xuất insulin, vaccine, hormone tăng trưởng nhờ vi khuẩn chuyển gene; liệu pháp gene.","Môi trường: Tạo vi sinh vật phân huỷ chất thải, dầu loang."],"e":["Hay nhầm: Không phải đạo đức sinh học chính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương XIV. Tiến hoá","l":[{"t":"Bài 49. Khái niệm tiến hoá và các hình thức chọn lọc","req":["Nêu được khái niệm tiến hoá; chọn lọc nhân tạo và chọn lọc tự nhiên."],"sum":["Tiến hoá là sự thay đổi đặc tính di truyền của quần thể sinh vật qua các thế hệ, dẫn đến hình thành các đặc điểm thích nghi, loài mới.","Khái niệm: Tiến hoá là sự thay đổi đặc tính di truyền của quần thể sinh vật qua các thế hệ, dẫn đến hình thành các đặc điểm thích nghi, loài mới.","Chọn lọc nhân tạo: Con người giữ lại những biến dị có lợi cho con người, loại bỏ biến dị không mong muốn, tạo ra các giống vật nuôi, cây trồng đa dạng (các giống gà,…","Chọn lọc tự nhiên (theo Darwin): Những cá thể mang biến dị có lợi cho sinh vật trong môi trường sống sẽ sống sót và sinh sản nhiều hơn; các biến dị có hại bị đào thải.","Ví dụ: Bướm sâu đo bạch dương ở vùng công nghiệp có tỉ lệ dạng đen tăng do thân cây bị ám khói đen."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 50. Cơ chế tiến hoá","req":["Trình bày được quan điểm của Lamarck, Darwin, thuyết tiến hoá hiện đại về cơ chế tiến hoá."],"sum":["Lamarck cho rằng ngoại cảnh thay đổi chậm chạp, sinh vật chủ động thích nghi; cơ quan dùng nhiều thì phát triển, không dùng thì tiêu biến và những đặc điểm đó được di truyền (quan điểm chưa chính…","Khái niệm: Lamarck cho rằng ngoại cảnh thay đổi chậm chạp, sinh vật chủ động thích nghi; cơ quan dùng nhiều thì phát triển, không dùng thì tiêu biến và những…","Darwin: Biến dị cá thể xuất hiện trong sinh sản là nguyên liệu; chọn lọc tự nhiên giữ lại biến dị có lợi, đào thải biến dị có hại; các loài sinh vật có…","Thuyết tiến hoá hiện đại: Nguyên liệu tiến hoá là đột biến và biến dị tổ hợp; các nhân tố tiến hoá gồm đột biến, di – nhập gene, chọn lọc tự nhiên, phiêu bạt di truyền, giao…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 51. Sự phát sinh và phát triển sự sống trên Trái Đất","req":["Trình bày được sơ lược sự phát sinh sự sống; các đại địa chất; sự phát sinh loài người."],"sum":["Sự sống phát sinh qua các giai đoạn: tiến hoá hoá học (hình thành các chất hữu cơ từ chất vô cơ), tiến hoá tiền sinh học (hình thành tế bào nguyên thuỷ), tiến hoá sinh học (từ tế bào nguyên thuỷ…","Sự sống phát sinh qua các giai đoạn: Tiến hoá hoá học (hình thành các chất hữu cơ từ chất vô cơ), tiến hoá tiền sinh học (hình thành tế bào nguyên thuỷ), tiến hoá sinh học (từ tế bào…","Lịch sử Trái Đất chia thành các đại: Thái cổ, Nguyên sinh, Cổ sinh, Trung sinh, Tân sinh.","Loài người (Homo sapiens) xuất hiện ở…: Loài người (Homo sapiens) xuất hiện ở đại Tân sinh, tiến hoá qua các dạng: người vượn (Australopithecus), người khéo léo (Homo habilis), người đứng…","Trái Đất hình thành khoảng 4,6 tỉ…: Trái Đất hình thành khoảng 4,6 tỉ năm trước; sự sống đầu tiên xuất hiện khoảng 3,5 tỉ năm trước."],"e":["Hay nhầm: Hình thành tế bào nguyên thuỷ."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương XI. Di truyền học Mendel. Cơ sở phân tử của hiện tượng di truyền","l":[{"t":"Bài tập nâng cao · Chương XI. Di truyền học Mendel. Cơ sở phân tử của hiện tượng di truyền (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương XII. Di truyền nhiễm sắc thể","l":[{"t":"Bài tập nâng cao · Chương XII. Di truyền nhiễm sắc thể (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương XIII. Di truyền học với con người và đời sống","l":[{"t":"Bài tập nâng cao · Chương XIII. Di truyền học với con người và đời sống (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương XIV. Tiến hoá","l":[{"t":"Bài tập nâng cao · Chương XIV. Tiến hoá (6 câu)","e":["Hay nhầm: Không phụ thuộc kiểu gene."],"q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 9","c":[{"t":"Chủ điểm 1. Our Communities (Cộng đồng của chúng ta)","l":[{"t":"Unit 1. Local community (Cộng đồng địa phương)","req":["Dùng từ để hỏi trước to-infinitive.","Hiểu và dùng các cụm động từ phần 1.","Nói và viết về làng nghề và người phục vụ cộng đồng."],"sum":["Từ để hỏi + to V rút gọn câu hỏi gián tiếp. Cụm động từ = động từ + tiểu từ, nghĩa riêng. Tân ngữ là đại từ thì đặt giữa: hand it down.","Từ để hỏi + to V: Từ để hỏi (what, where, how, who, when, which, whether) đứng trước to + V để rút gọn một mệnh đề hỏi gián tiếp. Thường đi sau know, wonder, ask,…","Cụm động từ (phrasal verbs): Gồm động từ + tiểu từ (up, down, on, out, off, around…), có nghĩa riêng, thường khác nghĩa của từng từ.","Cụm động từ tách được: Một số cụm có thể tách: hand sth down / hand down sth, pass sth down. Khi tân ngữ là đại từ thì bắt buộc đặt ở giữa.","Từ vựng nghề thủ công"],"e":["Sai: I don’t know why to go. → Đúng: I don’t know why we should go. (Why không đứng trước to V theo cách này, dùng why + mệnh đề.)","Sai: They hand down it to their children. → Đúng: They hand it down to their children. (Tân ngữ là đại từ (it, them, him…) thì đặt giữa động từ và tiểu từ.)","Hay nhầm: Why không đứng trước to V theo cách này.","Hay nhầm: Whom thường không đi như vậy ở đây.","Hay nhầm: Which one is không đi với to do.","Hay nhầm: Why không dùng trước to V."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. City life (Cuộc sống thành phố)","req":["Dùng đúng cấu trúc so sánh kép.","Hiểu và dùng các cụm động từ phần 2.","Nói và viết về cuộc sống thành phố."],"sum":["So sánh kép: The + so sánh hơn, the + so sánh hơn (song song) và so sánh hơn and so sánh hơn (tăng dần).","The + so sánh hơn, the + so sánh hơn: Diễn tả hai sự việc thay đổi song song: cái này tăng thì cái kia cũng tăng (hoặc giảm). Tính từ ngắn dùng -er; tính từ dài dùng more / less.","So sánh hơn lặp lại: Dạng comparative and comparative diễn tả sự tăng dần.","Cụm động từ phần 2","Từ vựng đời sống đô thị"],"e":["Sai: The city is getting more bigger. → Đúng: The city is getting bigger and bigger. (Tính từ ngắn dùng -er, không thêm more.)","Hay nhầm: Big không phải dạng so sánh hơn.","Hay nhầm: Big là tính từ ngắn nên không dùng more.","Hay nhầm: Expensiver sai quy tắc tính từ dài.","Hay nhầm: Most expensive là so sánh nhất.","Hay nhầm: The more expensive không dùng trong cấu trúc này."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Healthy living for teens (Lối sống lành mạnh cho thanh thiếu niên)","req":["Dùng câu điều kiện loại 1 với động từ khuyết thiếu.","Nói và viết về sức khỏe, căng thẳng và học tập.","Đưa ra lời khuyên."],"sum":["Điều kiện loại 1: If + hiện tại đơn, S + will / can / may / might / should / must + V. Không dùng will trong mệnh đề If.","Câu điều kiện loại 1: Nói về điều có thể xảy ra ở hiện tại hoặc tương lai.","Động từ khuyết thiếu ở mệnh đề chính: Ngoài will, các động từ khuyết thiếu khác làm thay đổi mức độ chắc chắn hoặc ý nghĩa.","Mệnh đề If và dấu phẩy","Unless: Unless = if … not.","Từ vựng sức khỏe và học tập"],"e":["Sai: If you will feel stressed, you should talk to a counsellor. → Đúng: If you feel stressed, you should talk to a counsellor. (Mệnh đề If luôn dùng hiện tại đơn, không dùng will.)","Hay nhầm: Không dùng will ở mệnh đề If.","Hay nhầm: Are không đi với V nguyên mẫu.","Hay nhầm: Distraction là điều làm xao nhãng.","Hay nhầm: Are không đi với V nguyên mẫu.","Hay nhầm: Might là ít chắc chắn hơn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 2. Our Heritage (Di sản của chúng ta)","l":[{"t":"Unit 4. Remembering the past (Nhớ về quá khứ)","req":["Dùng đúng thì quá khứ tiếp diễn.","Dùng wish + quá khứ đơn để diễn tả ước muốn.","Nói và viết về cuộc sống trong quá khứ."],"sum":["Quá khứ tiếp diễn: was / were + V-ing. Wish + quá khứ đơn: ước muốn trái với hiện tại, be dùng were ở mọi ngôi.","Quá khứ tiếp diễn: Diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ, hoặc hành động đang diễn ra thì có hành động khác xen vào.","When và While: When + quá khứ đơn (hành động xen vào), quá khứ tiếp diễn (hành động đang diễn ra). While + quá khứ tiếp diễn dùng cho hành động kéo dài song song.","Wish + quá khứ đơn: Diễn tả ước muốn trái với hiện tại. Với động từ be dùng were ở mọi ngôi.","Wish diễn tả điều không có thật","Phát âm /m/ và /l/"],"e":["Sai: I wish I was taller. / I wish I will be taller. → Đúng: I wish I were taller. (Dùng were ở mọi ngôi; không dùng will sau wish ở cấu trúc này, dùng would hoặc could.)","Hay nhầm: Did là quá khứ đơn, nhấn hành động hoàn thành.","Hay nhầm: Cooked nhấn hành động hoàn thành.","Hay nhầm: Will không dùng sau wish theo cấu trúc này.","Hay nhầm: Was là dạng thường ngày, nhưng trong câu ước dùng were.","Hay nhầm: Will be không dùng sau wish."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Our experiences (Những trải nghiệm của chúng ta)","req":["Dùng đúng thì hiện tại hoàn thành.","Phân biệt for / since và hiện tại hoàn thành với quá khứ đơn.","Nói và viết về những trải nghiệm."],"sum":["Hiện tại hoàn thành: have / has + V3. Mốc thời gian xác định trong quá khứ → dùng quá khứ đơn. Have gone to ≠ have been to.","Hiện tại hoàn thành: Diễn tả: (a) trải nghiệm trong đời cho đến nay; (b) hành động xảy ra trong quá khứ nhưng còn liên quan đến hiện tại; (c) hành động bắt đầu trong quá…","Dấu hiệu nhận biết","Động từ bất quy tắc cần nhớ","Gone to và been to","Tính từ chỉ cảm xúc về trải nghiệm"],"e":["Sai: I have visited Hue last week. → Đúng: I visited Hue last week. (Không dùng hiện tại hoàn thành với mốc thời gian xác định trong quá khứ (yesterday, last week, in 2019):…)","Hay nhầm: Visited là quá khứ đơn, cần mốc thời gian.","Hay nhầm: Am visiting là hiện tại tiếp diễn.","Hay nhầm: Didn’t dùng với quá khứ đơn.","Hay nhầm: Isn’t không đi với tried.","Hay nhầm: Doesn’t dùng với hiện tại đơn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 6. Vietnamese lifestyle: then and now (Lối sống của người Việt: xưa và nay)","req":["Dùng đúng động từ + to-infinitive và động từ + V-ing.","Phân biệt remember / forget + to V và + V-ing.","Nói và viết về sự thay đổi lối sống."],"sum":["Chỉ đi với to V: want, hope, decide… Chỉ đi với V-ing: enjoy, avoid, mind… Remember / forget đổi nghĩa theo to V hoặc V-ing.","Động từ chỉ đi với to V: want, hope, decide, plan, promise, learn, manage, agree, refuse, afford, expect, need, wish.","Động từ chỉ đi với V-ing: enjoy, avoid, mind, finish, keep, practise, suggest, consider, miss, imagine, give up.","Đi với cả to V và V-ing, nghĩa gần như không đổi: like, love, hate, prefer, begin, start, continue.","Động từ đổi nghĩa: remember / forget + to V: nhớ / quên phải làm. remember / forget + V-ing: nhớ / quên đã làm.","Từ vựng đổi mới trong lối sống"],"e":["Sai: She enjoys to cook. → Đúng: She enjoys cooking. (enjoy chỉ đi với V-ing.)","Hay nhầm: Decide không đi với V-ing.","Hay nhầm: Decide không đi với nguyên mẫu không to.","Hay nhầm: Visited không đứng sau decide.","Hay nhầm: Enjoy không đi với nguyên mẫu.","Hay nhầm: Promise không đi với V-ing."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 3. Our World (Thế giới của chúng ta)","l":[{"t":"Unit 7. Natural wonders of the world (Các kỳ quan thiên nhiên của thế giới)","req":["Tường thuật câu hỏi Yes / No bằng if / whether.","Lùi thì và đổi đại từ, trạng từ trong câu tường thuật.","Nói và viết về kỳ quan thiên nhiên."],"sum":["Tường thuật câu hỏi Yes / No: asked / wanted to know + if / whether + S + V, trật tự câu kể, lùi thì, không dấu hỏi.","Cấu trúc: Dùng ask hoặc want to know + if / whether + mệnh đề. Mệnh đề dùng trật tự câu khẳng định (chủ ngữ + động từ), không đảo trợ động từ, không dùng dấu…","Lùi thì","Đổi đại từ và trạng từ","If hay whether?: Cả hai đều dùng được, nhưng chỉ dùng whether khi có or not hoặc sau giới từ.","Từ vựng kỳ quan thiên nhiên"],"e":["Sai: He asked if did I like caves. → Đúng: He asked if I liked caves. (Dùng trật tự câu kể, không đảo trợ động từ.)","Hay nhầm: Do không dùng trong câu tường thuật.","Hay nhầm: Giữ nguyên hiện tại là chưa lùi thì.","Hay nhầm: Will enjoy chưa lùi thành would.","Hay nhầm: Am enjoying chưa lùi thành quá khứ tiếp diễn.","Hay nhầm: Visited không phải would visit."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. Tourism (Du lịch)","req":["Dùng đúng đại từ quan hệ who, which, whose.","Hiểu và dùng từ vựng du lịch.","Nói và viết về một chuyến du lịch."],"sum":["Đại từ quan hệ: who (người), which (vật, sự việc), whose (sở hữu) + danh từ. Có thể dùng that thay who / which.","Who, which, whose: Đại từ quan hệ đứng sau danh từ để nối một mệnh đề phụ cho biết thêm về danh từ đó.","Whose đi kèm danh từ: Whose luôn có một danh từ ngay sau nó.","Làm chủ ngữ hay tân ngữ: Who và which có thể là chủ ngữ hoặc tân ngữ. Làm chủ ngữ thì bắt buộc phải có; làm tân ngữ thì có thể lược bỏ trong mệnh đề xác định.","That thay cho who / which: Có thể dùng that thay cho who hoặc which trong mệnh đề xác định.","Từ vựng du lịch"],"e":["Sai: He is the man who’s son is a travel agent. → Đúng: He is the man whose son is a travel agent. (Không dùng whose như who’s (= who is).)","Hay nhầm: Who thay cho người nhưng không thể thay him + danh từ.","Hay nhầm: Whom là tân ngữ, không dùng trước danh từ.","Hay nhầm: Whose cần có danh từ theo sau.","Hay nhầm: What không dùng làm đại từ quan hệ ở đây.","Hay nhầm: Which không đi trực tiếp với danh từ theo sau."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 9. World Englishes (Các biến thể tiếng Anh trên thế giới)","req":["Dùng đúng mệnh đề quan hệ xác định.","Biết khi nào có thể lược đại từ quan hệ.","Nói và viết về việc học tiếng Anh."],"sum":["Mệnh đề quan hệ xác định: cho thông tin cần thiết, không dấu phẩy. who (người), which (vật), that (cả hai), whose (sở hữu).","Mệnh đề quan hệ xác định: Cho thông tin cần thiết để biết người hay vật nào đang được nói đến. Không có mệnh đề này, câu thiếu nghĩa rõ ràng. Không dùng dấu phẩy.","Các đại từ quan hệ","Chủ ngữ hay tân ngữ: Who / which / that làm chủ ngữ thì bắt buộc phải có; làm tân ngữ thì có thể lược bỏ.","Whose + danh từ","Trọng âm từ tận cùng -ion và -ity: Nhấn âm tiết ngay trước đuôi."],"e":["Hay nhầm: Who không thể thay her son.","Hay nhầm: That không dùng để chỉ sở hữu.","Hay nhầm: What không dùng làm đại từ quan hệ ở đây.","Hay nhầm: Whose cần danh từ theo sau.","Hay nhầm: Không thể lược đại từ làm chủ ngữ.","Hay nhầm: Thiếu mạo từ a trước translator."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 4. Visions of the Future (Tầm nhìn tương lai)","l":[{"t":"Unit 10. Planet Earth (Hành tinh Trái Đất)","req":["Dùng đúng mệnh đề quan hệ không xác định và dấu phẩy.","Phân biệt mệnh đề xác định và không xác định.","Nói và viết về Trái Đất và môi trường."],"sum":["Mệnh đề quan hệ không xác định: thông tin phụ, có dấu phẩy, không dùng that, không lược bỏ đại từ quan hệ.","Mệnh đề không xác định: Thêm thông tin phụ về danh từ đã rõ nghĩa (tên riêng, vật duy nhất…). Nếu bỏ đi, câu vẫn đủ nghĩa.","Dấu phẩy và đại từ quan hệ: Luôn có dấu phẩy (hoặc hai dấu phẩy) ngăn với phần còn lại. Dùng who cho người, which cho vật, whose cho sở hữu.","Không được lược bỏ đại từ quan hệ: Đại từ quan hệ trong mệnh đề không xác định KHÔNG được lược bỏ, kể cả khi nó làm tân ngữ.","So sánh hai loại mệnh đề","Từ vựng Trái Đất và môi trường"],"e":["Sai: Neil Armstrong, that was the first man on the Moon, died in 2012. → Đúng: Neil Armstrong, who was the first man on the Moon, died in 2012. (KHÔNG dùng that trong mệnh đề không xác định.)","Hay nhầm: That không dùng trong mệnh đề không xác định.","Hay nhầm: That không dùng trong mệnh đề không xác định.","Hay nhầm: That không dùng trong mệnh đề không xác định.","Hay nhầm: Who không thay cho her daughter.","Hay nhầm: That không dùng trong mệnh đề không xác định."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 11. Electronic devices (Thiết bị điện tử)","req":["Dùng đúng suggest / advise / recommend + V-ing hoặc that-clause.","Nói về các thiết bị điện tử và vật liệu.","Nói và viết về thiết bị em thích."],"sum":["suggest / advise / recommend + V-ing hoặc + (that) + S + (should) + V nguyên mẫu. Suggest KHÔNG đi với tân ngữ + to V.","Hai cấu trúc chính: Suggest, advise, recommend dùng để đưa lời khuyên hoặc đề nghị.","Động từ nguyên mẫu sau that-clause: Dùng động từ nguyên mẫu không chia, kể cả với he / she / it. Có thể thêm should.","Advise và suggest khác nhau: Advise còn dùng được với tân ngữ + to V. Suggest KHÔNG đi với tân ngữ + to V.","Từ vựng thiết bị và vật liệu","Kỹ năng: Khi đọc, có thể đoán nghĩa từ trong ngữ cảnh dựa vào các từ xung quanh. Khi nói, nhấn mạnh các từ nội dung trong câu."],"e":["Sai: She suggested that he buys a smartwatch. → Đúng: She suggested that he buy a smartwatch. (Sau that-clause dùng động từ nguyên mẫu, không thêm -s.)","Sai: She suggested me to buy a laptop. → Đúng: She suggested buying a laptop. / She advised me to buy a laptop. (Không nói suggest me to buy.)","Hay nhầm: Suggest không đi với to V.","Hay nhầm: Suggest + V nguyên mẫu cần có that-clause.","Hay nhầm: Would không dùng trong cấu trúc này.","Hay nhầm: Can không dùng trong cấu trúc này."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 12. Career choices (Lựa chọn nghề nghiệp)","req":["Dùng đúng mệnh đề nhượng bộ, kết quả và lý do.","Nói về các nghề nghiệp và phẩm chất.","Nói và viết về nghề em muốn làm."],"sum":["Nhượng bộ: although + mệnh đề. Kết quả: so … that / such … that. Lý do: because / since / as + mệnh đề, because of + N.","Nhượng bộ (concession): Although, though, even though + mệnh đề, diễn tả hai ý trái ngược nhau.","Kết quả (result): so + mệnh đề; so + adj / adv + that; such + (a / an) + adj + noun + that.","Lý do (reason): because, since, as + mệnh đề; because of + danh từ / V-ing. Because nhấn mạnh lý do mới; since và as dùng khi lý do đã rõ.","Although với despite / in spite of: Although + mệnh đề; despite / in spite of + danh từ hoặc V-ing.","Từ vựng nghề nghiệp và tính cách"],"e":["Sai: Although the job is demanding, but it is rewarding. → Đúng: Although the job is demanding, it is rewarding. (Không dùng but cùng với although trong cùng câu.)","Hay nhầm: Even though chỉ nhượng bộ.","Hay nhầm: Bartender là người pha chế.","Hay nhầm: So không đi với a + danh từ.","Hay nhầm: Surgeon là bác sĩ phẫu thuật.","Hay nhầm: Because không đi sau so + adv theo cấu trúc này."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 9","c":[{"t":"Chương 1. Thế giới từ năm 1918 đến năm 1945","l":[{"t":"Bài 1. Nước Nga và Liên Xô từ năm 1918 đến năm 1945","req":["Nêu được những nét chính về nước Nga trước khi Liên Xô thành lập; sự thành lập Liên Xô; thành tựu và hạn chế của công cuộc xây dựng chủ nghĩa xã hội."],"sum":["Sau Cách mạng tháng Mười, nước Nga Xô viết phải chống thù trong giặc ngoài (1918–1920), thực hiện Chính sách cộng sản thời chiến.","Khái niệm: Sau Cách mạng tháng Mười, nước Nga Xô viết phải chống thù trong giặc ngoài (1918–1920), thực hiện Chính sách cộng sản thời chiến.","Từ khoá cần ghi nhớ: Nước Nga Xô viết;","Mốc sự kiện cần nhớ: 1921: thực hiện NEP; tháng 12/1922: thành lập Liên Xô","Tháng 12/1922, Liên bang Cộng hoà xã…: Tháng 12/1922, Liên bang Cộng hoà xã hội chủ nghĩa Xô viết (Liên Xô) được thành lập.","Công cuộc xây dựng chủ nghĩa xã hội (1925–1941): Công nghiệp hoá, tập thể hoá nông nghiệp;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Châu Âu và nước Mỹ từ năm 1918 đến năm 1945","req":["Trình bày được phong trào cách mạng 1918–1923, sự thành lập Quốc tế Cộng sản; cuộc đại suy thoái 1929–1933; chủ nghĩa phát xít; nước Mỹ giữa hai cuộc chiến tranh."],"sum":["Sau Chiến tranh thế giới thứ nhất, phong trào cách mạng bùng nổ ở châu Âu (1918–1923). Tháng 3/1919 Quốc tế Cộng sản (Quốc tế thứ ba) được thành lập ở Mát-xcơ-va.","Khái niệm: Sau Chiến tranh thế giới thứ nhất, phong trào cách mạng bùng nổ ở châu Âu (1918–1923).","Từ khoá cần ghi nhớ: Quốc tế Cộng sản;","Mốc sự kiện cần nhớ: Tháng 3/1919: thành lập Quốc tế Cộng sản;","Cuộc đại suy thoái kinh tế 1929–1933…: Cuộc đại suy thoái kinh tế 1929–1933 bắt đầu từ Mỹ, lan ra toàn thế giới tư bản, gây hậu quả nặng nề (sản xuất đình đốn, thất nghiệp hàng chục triệu…","Để thoát khủng hoảng, Mỹ, Anh, Pháp cải cách kinh tế – xã hội (Mỹ: Chính sách mới của Tổng thống Ru-dơ-ven);"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Châu Á từ năm 1918 đến năm 1945","req":["Nêu được những nét chính về Nhật Bản, phong trào độc lập dân tộc ở châu Á (Trung Quốc, Đông Nam Á) từ năm 1918 đến năm 1945."],"sum":["Nhật Bản: sau Chiến tranh thế giới thứ nhất kinh tế phát triển nhưng không ổn định; khủng hoảng 1929–1933 khiến Nhật quân phiệt hoá, gây chiến tranh xâm lược Trung Quốc (1931, 1937).","Nhật Bản: Sau Chiến tranh thế giới thứ nhất kinh tế phát triển nhưng không ổn định; khủng hoảng 1929–1933 khiến Nhật quân phiệt hoá, gây chiến tranh xâm lược…","Từ khoá cần ghi nhớ: Nhật Bản quân phiệt hoá; phong trào Ngũ tứ;","Mốc sự kiện cần nhớ: 4/5/1919: phong trào Ngũ tứ;","Trung Quốc: Phong trào Ngũ tứ (4/5/1919) mở đầu cách mạng dân chủ mới; năm 1921 Đảng Cộng sản Trung Quốc thành lập; cuộc kháng chiến chống Nhật (1937–1945).","Đông Nam Á: Phong trào độc lập dân tộc phát triển; các đảng cộng sản ra đời (In-đô-nê-xi-a 1920, Việt Nam 1930…); phong trào của giai cấp tư sản, tiểu tư sản…"],"e":["Hay nhầm: Thành lập nước CHND Trung Hoa."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Chiến tranh thế giới thứ hai (1939 – 1945)","req":["Trình bày được nguyên nhân, diễn biến chính, kết cục của Chiến tranh thế giới thứ hai; vai trò của Liên Xô, Mỹ, Anh; hậu quả của chiến tranh."],"sum":["Nguyên nhân: mâu thuẫn giữa các nước đế quốc về thị trường, thuộc địa; chủ nghĩa phát xít ra đời; chính sách nhân nhượng của Anh, Pháp, Mỹ.","Nguyên nhân: Mâu thuẫn giữa các nước đế quốc về thị trường, thuộc địa; chủ nghĩa phát xít ra đời; chính sách nhân nhượng của Anh, Pháp, Mỹ.","Từ khoá cần ghi nhớ: Phát xít;","Mốc sự kiện cần nhớ: 1/9/1939: Đức tấn công Ba Lan;","Diễn biến chính: Đức chiếm phần lớn châu Âu; ngày 22/6/1941 Đức tấn công Liên Xô; ngày 7/12/1941 Nhật tấn công Trân Châu Cảng, Mỹ tham chiến.","Kết thúc: Ngày 9/5/1945 Đức đầu hàng không điều kiện;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","l":[{"t":"Bài 5. Phong trào dân tộc dân chủ những năm 1918 – 1930","req":["Trình bày được những nét chính về cuộc khai thác thuộc địa lần thứ hai của Pháp và tác động; phong trào dân tộc dân chủ 1918–1930."],"sum":["Sau Chiến tranh thế giới thứ nhất, Pháp tiến hành khai thác thuộc địa lần thứ hai (1919–1929) với quy mô lớn, tập trung vào đồn điền cao su, khai mỏ (than).","Khái niệm: Sau Chiến tranh thế giới thứ nhất, Pháp tiến hành khai thác thuộc địa lần thứ hai (1919–1929) với quy mô lớn, tập trung vào đồn điền cao su, khai mỏ…","Từ khoá cần ghi nhớ: Khai thác thuộc địa lần thứ hai;","Mốc sự kiện cần nhớ: Khai thác thuộc địa lần thứ hai diễn ra từ 1919 đến 1929","Xã hội Việt Nam phân hoá sâu sắc: Giai cấp địa chủ, nông dân; giai cấp tư sản (tư sản mại bản, tư sản dân tộc), tiểu tư sản, công nhân phát triển nhanh.","Phong trào của tư sản, tiểu tư sản: Chấn hưng nội hoá, bài trừ ngoại hoá (1919); chống độc quyền cảng Sài Gòn (1923);"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Hoạt động của Nguyễn Ái Quốc và sự thành lập Đảng Cộng sản Việt Nam","req":["Nêu được những nét chính về hoạt động của Nguyễn Ái Quốc; sự thành lập Đảng Cộng sản Việt Nam và ý nghĩa."],"sum":["Năm 1919, Nguyễn Ái Quốc gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Véc-xai. Năm 1920 đọc Sơ thảo luận cương về vấn đề dân tộc và thuộc địa của Lê-nin, tìm thấy con đường cứu nước; tham gia…","Khái niệm: Năm 1919, Nguyễn Ái Quốc gửi Bản yêu sách của nhân dân An Nam tới Hội nghị Véc-xai.","Từ khoá cần ghi nhớ: Bản yêu sách;","Mốc sự kiện cần nhớ: 1919: Bản yêu sách gửi Hội nghị Véc-xai;","Năm 1925, Nguyễn Ái Quốc thành lập…: Năm 1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu (Trung Quốc), mở lớp huấn luyện cán bộ; năm 1927 tác phẩm Đường…","Năm 1929, ba tổ chức cộng sản ra đời: Đông Dương Cộng sản đảng, An Nam Cộng sản đảng, Đông Dương Cộng sản liên đoàn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Phong trào cách mạng Việt Nam thời kì 1930 – 1939","req":["Trình bày được phong trào cách mạng 1930–1931, đỉnh cao là Xô viết Nghệ – Tĩnh; phong trào dân chủ 1936–1939."],"sum":["Phong trào cách mạng 1930–1931 bùng nổ dưới sự lãnh đạo của Đảng, đỉnh cao là Xô viết Nghệ – Tĩnh: chính quyền Xô viết được thành lập ở nhiều xã, thực hiện nhiều chính sách tiến bộ (giảm tô, xoá nợ,…","Khái niệm: Phong trào cách mạng 1930–1931 bùng nổ dưới sự lãnh đạo của Đảng, đỉnh cao là Xô viết Nghệ – Tĩnh: chính quyền Xô viết được thành lập ở nhiều xã,…","Từ khoá cần ghi nhớ: Xô viết Nghệ – Tĩnh;","Mốc sự kiện cần nhớ: 1930–1931: phong trào và Xô viết Nghệ – Tĩnh; tháng 10/1930: đổi tên thành Đảng Cộng sản Đông Dương","Tháng 10/1930, Hội nghị Ban Chấp hành…: Tháng 10/1930, Hội nghị Ban Chấp hành Trung ương lần thứ nhất đổi tên Đảng thành Đảng Cộng sản Đông Dương, thông qua Luận cương chính trị do Trần…","Phong trào dân chủ 1936–1939: Đấu tranh đòi tự do, dân chủ, cơm áo, hoà bình với hình thức công khai, hợp pháp;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Cách mạng tháng Tám năm 1945","req":["Trình bày được những nét chính về quá trình chuẩn bị, diễn biến, ý nghĩa, nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945; vai trò của Nguyễn Ái Quốc và Đảng."],"sum":["Chuẩn bị: tháng 1/1941 Nguyễn Ái Quốc về nước; Hội nghị Trung ương 8 (5/1941) quyết định thành lập Mặt trận Việt Minh (19/5/1941), đặt nhiệm vụ giải phóng dân tộc lên hàng đầu.","Chuẩn bị: Tháng 1/1941 Nguyễn Ái Quốc về nước;","Từ khoá cần ghi nhớ: Việt Minh;","Mốc sự kiện cần nhớ: Tháng 5/1941: Hội nghị Trung ương 8;","Ngày 9/3/1945 Nhật đảo chính Pháp: Đảng phát động cao trào kháng Nhật cứu nước.","Diễn biến: Giành chính quyền ở Hà Nội (19/8), Huế (23/8), Sài Gòn (25/8);"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Thế giới từ năm 1945 đến năm 1991","l":[{"t":"Bài 9. Chiến tranh lạnh (1947 – 1989)","req":["Nêu được nguyên nhân, những biểu hiện và hậu quả của Chiến tranh lạnh."],"sum":["Sau Chiến tranh thế giới thứ hai, Liên Xô và Mỹ từ đồng minh trở thành đối đầu do khác biệt về mục tiêu, chiến lược.","Khái niệm: Sau Chiến tranh thế giới thứ hai, Liên Xô và Mỹ từ đồng minh trở thành đối đầu do khác biệt về mục tiêu, chiến lược.","Từ khoá cần ghi nhớ: Chiến tranh lạnh; học thuyết Tru-man;","Mốc sự kiện cần nhớ: 1947: học thuyết Tru-man;","Biểu hiện: Mỹ thực hiện kế hoạch Mác-san (1947) viện trợ Tây Âu; thành lập khối quân sự NATO (1949);","Tháng 12/1989, tại Man-ta, Liên Xô và…: Tháng 12/1989, tại Man-ta, Liên Xô và Mỹ tuyên bố chấm dứt Chiến tranh lạnh."],"e":["Hay nhầm: Cùng năm nhưng không phải mở đầu."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Liên Xô và các nước Đông Âu từ năm 1945 đến năm 1991","req":["Trình bày được tình hình chính trị, kinh tế, xã hội Liên Xô và Đông Âu; nguyên nhân sụp đổ của chế độ xã hội chủ nghĩa."],"sum":["Liên Xô: khôi phục kinh tế sau chiến tranh (1945–1950); năm 1949 chế tạo thành công bom nguyên tử; năm 1957 phóng vệ tinh nhân tạo đầu tiên; năm 1961 Ga-ga-rin bay vào vũ trụ.","Liên Xô: Khôi phục kinh tế sau chiến tranh (1945–1950); năm 1949 chế tạo thành công bom nguyên tử; năm 1957 phóng vệ tinh nhân tạo đầu tiên; năm 1961…","Từ khoá cần ghi nhớ: Khôi phục kinh tế; bom nguyên tử; vệ tinh nhân tạo;","Mốc sự kiện cần nhớ: 1949: bom nguyên tử;","Đông Âu: Sau 1945 các nước dân chủ nhân dân ra đời, tiến hành xây dựng chủ nghĩa xã hội.","Từ những năm 70, khủng hoảng kinh…: Từ những năm 70, khủng hoảng kinh tế – chính trị; năm 1985 Gooc-ba-chốp tiến hành cải tổ nhưng thất bại."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 11. Nước Mỹ và các nước Tây Âu từ năm 1945 đến năm 1991","req":["Nêu được những nét chính về kinh tế, chính trị của Mỹ và Tây Âu; quá trình liên kết khu vực ở châu Âu."],"sum":["Mỹ: sau Chiến tranh thế giới thứ hai trở thành nước tư bản giàu mạnh nhất, chiếm hơn 1/2 sản lượng công nghiệp thế giới (1945–1950); là trung tâm kinh tế – tài chính lớn nhất;","Khái niệm: Mỹ: sau Chiến tranh thế giới thứ hai trở thành nước tư bản giàu mạnh nhất, chiếm hơn 1/2 sản lượng công nghiệp thế giới (1945–1950); là trung tâm…","Từ khoá cần ghi nhớ: Bá chủ thế giới; kinh tế tư bản; kế hoạch Mác-san; liên minh;","Mốc sự kiện cần nhớ: 1947: kế hoạch Mác-san viện trợ Tây Âu","Tây Âu: Nhờ viện trợ của Mỹ (kế hoạch Mác-san) khôi phục kinh tế; từ những năm 50–70 phát triển nhanh, trở thành một trong ba trung tâm kinh tế – tài chính…","Liên kết khu vực: Năm 1957 thành lập Cộng đồng Kinh tế châu Âu (EEC); năm 1967 thành lập Cộng đồng châu Âu (EC); năm 1993 trở thành Liên minh châu Âu (EU)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Khu vực Mỹ La-tinh và châu Á từ năm 1945 đến năm 1991","req":["Nêu được những nét chính về Mỹ La-tinh, cách mạng Cu-ba; Trung Quốc, Nhật Bản, Đông Nam Á và sự thành lập ASEAN; Ấn Độ."],"sum":["Mỹ La-tinh: phong trào đấu tranh chống chế độ độc tài thân Mỹ phát triển. Cách mạng Cu-ba do Phi-đen Ca-xtơ-rô lãnh đạo thắng lợi (1/1/1959);","Mỹ La-tinh: Phong trào đấu tranh chống chế độ độc tài thân Mỹ phát triển.","Từ khoá cần ghi nhớ: Mỹ La-tinh;","Mốc sự kiện cần nhớ: 1/1/1959: cách mạng Cu-ba thắng lợi;","Trung Quốc: Ngày 1/10/1949 nước Cộng hoà Nhân dân Trung Hoa thành lập; từ năm 1978 tiến hành cải cách, mở cửa, kinh tế phát triển nhanh.","Đông Nam Á: Sau 1945 hầu hết các nước giành độc lập."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","l":[{"t":"Bài 13. Việt Nam trong năm đầu sau Cách mạng tháng Tám năm 1945","req":["Nêu được tình hình nước Việt Nam Dân chủ Cộng hoà sau Cách mạng tháng Tám; những biện pháp xây dựng chính quyền, giải quyết khó khăn, bảo vệ độc lập."],"sum":["Sau Cách mạng tháng Tám, nước ta đứng trước muôn vàn khó khăn: thù trong giặc ngoài (quân Trung Hoa Dân quốc ở miền Bắc, quân Anh mở đường cho Pháp ở miền Nam), nạn đói, nạn dốt, ngân sách trống…","Sau Cách mạng tháng Tám, nước ta đứng trước muôn vàn khó khăn: Thù trong giặc ngoài (quân Trung Hoa Dân quốc ở miền Bắc, quân Anh mở đường cho Pháp ở miền Nam), nạn đói, nạn dốt, ngân sách trống rỗng – tình thế…","Từ khoá cần ghi nhớ: Thù trong giặc ngoài; ngàn cân treo sợi tóc; tổng tuyển cử;","Mốc sự kiện cần nhớ: 6/1/1946: tổng tuyển cử bầu Quốc hội; năm 1946: thông qua Hiến pháp đầu tiên","Xây dựng chính quyền: Ngày 6/1/1946 tổng tuyển cử bầu Quốc hội; năm 1946 thông qua Hiến pháp đầu tiên.","Đối phó ngoại xâm: Tạm hoà hoãn với Trung Hoa Dân quốc ở miền Bắc để tập trung chống Pháp ở Nam Bộ (Pháp gây hấn ở Sài Gòn ngày 23/9/1945); kí Hiệp định Sơ bộ…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 14. Việt Nam kháng chiến chống thực dân Pháp xâm lược giai đoạn 1946 – 1950","req":["Trình bày được nguyên nhân bùng nổ cuộc kháng chiến toàn quốc; đường lối kháng chiến; chiến dịch Việt Bắc 1947 và Biên giới 1950."],"sum":["Cuối năm 1946, Pháp bội ước, gây hấn ở Hải Phòng, Lạng Sơn, Hà Nội. Đêm 19/12/1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến.","Khái niệm: Cuối năm 1946, Pháp bội ước, gây hấn ở Hải Phòng, Lạng Sơn, Hà Nội.","Từ khoá cần ghi nhớ: Lời kêu gọi toàn quốc kháng chiến; toàn dân, toàn diện, trường kì;","Mốc sự kiện cần nhớ: 19/12/1946: Lời kêu gọi toàn quốc kháng chiến; thu – đông 1947: chiến dịch Việt Bắc","Đường lối kháng chiến: Toàn dân, toàn diện, trường kì, tự lực cánh sinh và tranh thủ sự ủng hộ quốc tế.","Chiến dịch Việt Bắc thu – đông 1947: Đánh bại cuộc tấn công lên căn cứ địa Việt Bắc của Pháp, làm phá sản kế hoạch \"đánh nhanh thắng nhanh\"."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Việt Nam kháng chiến chống thực dân Pháp xâm lược giai đoạn 1951 – 1954","req":["Trình bày được những nét chính về Đại hội II của Đảng; chiến cuộc Đông – Xuân 1953–1954 và chiến dịch Điện Biên Phủ; Hiệp định Giơ-ne-vơ."],"sum":["Tháng 2/1951, Đại hội đại biểu toàn quốc lần thứ II của Đảng quyết định đưa Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam.","Khái niệm: Tháng 2/1951, Đại hội đại biểu toàn quốc lần thứ II của Đảng quyết định đưa Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam.","Từ khoá cần ghi nhớ: Đảng Lao động Việt Nam; kế hoạch Na-va;","Mốc sự kiện cần nhớ: Tháng 2/1951: Đảng Lao động Việt Nam;","Năm 1953, Pháp đề ra kế hoạch Na-va: Ta mở cuộc tiến công chiến lược Đông – Xuân 1953–1954, buộc địch phân tán lực lượng.","Chiến dịch Điện Biên Phủ (13/3 –…: Chiến dịch Điện Biên Phủ (13/3 – 7/5/1954), do Đại tướng Võ Nguyên Giáp chỉ huy, qua ba đợt tiến công, tiêu diệt toàn bộ tập đoàn cứ điểm, bắt sống…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 16. Việt Nam kháng chiến chống Mỹ, cứu nước, thống nhất đất nước giai đoạn 1954 – 1965","req":["Nêu được tình hình hai miền sau Hiệp định Giơ-ne-vơ; phong trào Đồng khởi; công cuộc xây dựng CNXH ở miền Bắc; chiến lược \"Chiến tranh đặc biệt\" và cuộc đấu tranh chống lại."],"sum":["Sau năm 1954, đất nước bị chia cắt làm hai miền: miền Bắc hoàn toàn giải phóng, đi lên chủ nghĩa xã hội; miền Nam Mỹ thay chân Pháp, dựng chính quyền Ngô Đình Diệm.","Sau năm 1954, đất nước bị chia cắt làm hai miền: Miền Bắc hoàn toàn giải phóng, đi lên chủ nghĩa xã hội; miền Nam Mỹ thay chân Pháp, dựng chính quyền Ngô Đình Diệm.","Từ khoá cần ghi nhớ: Chia cắt hai miền;","Mốc sự kiện cần nhớ: 17/1/1960: Đồng khởi Bến Tre;","Phong trào \"Đồng khởi\" (1959–1960), tiêu biểu…: Phong trào \"Đồng khởi\" (1959–1960), tiêu biểu ở Bến Tre (17/1/1960), làm lung lay chính quyền Ngô Đình Diệm.","Tháng 9/1960, Đại hội đại biểu toàn…: Tháng 9/1960, Đại hội đại biểu toàn quốc lần thứ III của Đảng đề ra nhiệm vụ cách mạng hai miền."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Việt Nam kháng chiến chống Mỹ, cứu nước, thống nhất đất nước giai đoạn 1965 – 1975","req":["Trình bày được cuộc chiến đấu chống \"Chiến tranh cục bộ\", \"Việt Nam hoá chiến tranh\"; Hiệp định Pa-ri; cuộc Tổng tiến công và nổi dậy mùa Xuân 1975."],"sum":["\"Chiến tranh cục bộ\" (1965–1968): Mỹ đưa quân viễn chinh vào miền Nam, mở rộng chiến tranh phá hoại miền Bắc.","\"Chiến tranh cục bộ\" (1965–1968): Mỹ đưa quân viễn chinh vào miền Nam, mở rộng chiến tranh phá hoại miền Bắc.","Từ khoá cần ghi nhớ: Chiến tranh cục bộ;","Mốc sự kiện cần nhớ: 8/1965: Vạn Tường;","\"Việt Nam hoá chiến tranh\" (1969–1973): Ta giành thắng lợi trong cuộc tiến công chiến lược năm 1972; miền Bắc đánh bại cuộc tập kích bằng B52 cuối năm 1972 (\"Điện Biên Phủ trên không\").","Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 gồm ba chiến dịch: Tây Nguyên (4/3 – 24/3), Huế – Đà Nẵng (21/3 – 29/3), Hồ Chí Minh (26/4 – 30/4)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 5. Thế giới từ năm 1991 đến nay","l":[{"t":"Bài 18. Trật tự thế giới mới từ năm 1991 đến nay. Liên bang Nga và nước Mỹ từ năm 1991 đến nay","req":["Nêu được xu hướng phát triển của thế giới sau Chiến tranh lạnh; những nét chính về Liên bang Nga và nước Mỹ từ năm 1991 đến nay."],"sum":["Sau Chiến tranh lạnh, trật tự hai cực I-an-ta sụp đổ; thế giới đang hình thành trật tự đa cực với nhiều trung tâm (Mỹ, EU, Nhật Bản, Nga, Trung Quốc…).","Khái niệm: Sau Chiến tranh lạnh, trật tự hai cực I-an-ta sụp đổ; thế giới đang hình thành trật tự đa cực với nhiều trung tâm (Mỹ, EU, Nhật Bản, Nga, Trung…","Từ khoá cần ghi nhớ: Trật tự hai cực I-an-ta; trật tự đa cực;","Mốc sự kiện cần nhớ: 1991: trật tự hai cực I-an-ta sụp đổ; từ năm 2000: kinh tế Nga phục hồi","Liên bang Nga: Kế tục Liên Xô; thập niên 90 gặp nhiều khó khăn; từ năm 2000 kinh tế phục hồi, vị thế quốc tế được nâng cao.","Mỹ: vẫn là cường quốc hàng đầu…: Mỹ: vẫn là cường quốc hàng đầu về kinh tế, quân sự, khoa học – kĩ thuật;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Châu Á từ năm 1991 đến nay","req":["Nêu được sự phát triển của khu vực châu Á từ năm 1991; Trung Quốc, Nhật Bản, Hàn Quốc, Ấn Độ; sự phát triển của ASEAN."],"sum":["Châu Á trở thành khu vực năng động, phát triển nhanh nhất thế giới. Trung Quốc tiếp tục cải cách, mở cửa, trở thành nền kinh tế lớn thứ hai thế giới (2010).","Khái niệm: Châu Á trở thành khu vực năng động, phát triển nhanh nhất thế giới.","Từ khoá cần ghi nhớ: Châu Á năng động;","Mốc sự kiện cần nhớ: 1995: Việt Nam gia nhập ASEAN;","ASEAN mở rộng: Việt Nam gia nhập (1995), Lào và Mi-an-ma (1997), Cam-pu-chia (1999) – ASEAN có 10 thành viên.","Thách thức: Tranh chấp lãnh thổ, chủ quyền biển đảo; chênh lệch phát triển; thiên tai, biến đổi khí hậu."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 6. Việt Nam từ năm 1976 đến nay","l":[{"t":"Bài 20. Việt Nam từ năm 1976 đến nay","req":["Nêu được những nét chính về thống nhất đất nước về mặt nhà nước, đấu tranh bảo vệ Tổ quốc (1976–1991); công cuộc Đổi mới từ năm 1986 đến nay: thành tựu và hạn chế."],"sum":["Ngày 25/4/1976, tổng tuyển cử bầu Quốc hội chung cả nước. Tháng 7/1976 Quốc hội quyết định đặt tên nước là Cộng hoà xã hội chủ nghĩa Việt Nam, thủ đô Hà Nội, Thành phố Sài Gòn – Gia Định đổi tên…","Ngày 25/4/1976, tổng tuyển cử bầu Quốc hội chung cả nước: Tháng 7/1976 Quốc hội quyết định đặt tên nước là Cộng hoà xã hội chủ nghĩa Việt Nam, thủ đô Hà Nội, Thành phố Sài Gòn – Gia Định đổi tên thành Thành…","Từ khoá cần ghi nhớ: Tổng tuyển cử;","Mốc sự kiện cần nhớ: 25/4/1976: tổng tuyển cử bầu Quốc hội chung cả nước; tháng 7/1976: đặt tên nước Cộng hoà xã hội chủ nghĩa Việt Nam;","Đấu tranh bảo vệ Tổ quốc: Chiến đấu bảo vệ biên giới Tây Nam (1979) và biên giới phía Bắc (tháng 2/1979); bảo vệ chủ quyền biển đảo (năm 1988 ở Trường Sa – Gạc Ma).","Do sai lầm trong chính sách, cuối…: Do sai lầm trong chính sách, cuối những năm 1970 đất nước lâm vào khủng hoảng kinh tế – xã hội."],"e":["Hay nhầm: Việt Nam Dân chủ Cộng hoà."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương 7. Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá","l":[{"t":"Bài 21. Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá","req":["Nêu được những thành tựu chủ yếu và tác động của cách mạng khoa học – kĩ thuật; xu thế toàn cầu hoá và tác động."],"sum":["Cách mạng khoa học – kĩ thuật lần thứ hai bắt đầu từ những năm 40 của thế kỉ XX. Thành tựu: khoa học cơ bản; công cụ sản xuất mới (máy tính, máy tự động, rô-bốt); nguồn năng lượng mới (nguyên tử,…","Khái niệm: Cách mạng khoa học – kĩ thuật lần thứ hai bắt đầu từ những năm 40 của thế kỉ XX.","Từ khoá cần ghi nhớ: Cách mạng khoa học – kĩ thuật lần thứ hai; máy tính; rô-bốt; năng lượng nguyên tử; toàn cầu hoá; vật liệu mới.","Mốc sự kiện cần nhớ: Từ những năm 40 thế kỉ XX;","Tác động: Tăng năng suất lao động, thay đổi cơ cấu dân cư lao động, nâng cao chất lượng cuộc sống; mặt trái: ô nhiễm môi trường, vũ khí huỷ diệt, tai nạn lao…","Toàn cầu hoá là quá trình tăng…: Toàn cầu hoá là quá trình tăng lên mạnh mẽ những mối liên hệ, ảnh hưởng, tác động lẫn nhau giữa các quốc gia, dân tộc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề chung. Đô thị: lịch sử và hiện tại","l":[{"t":"Chủ đề chung. Đô thị: lịch sử và hiện tại","req":["Nêu được sự hình thành, phát triển của một số đô thị ở Việt Nam trong lịch sử; vai trò của đô thị và vấn đề đô thị hoá hiện nay."],"sum":["Đô thị là nơi dân cư tập trung đông, hoạt động chủ yếu là công nghiệp, thương mại, dịch vụ; là trung tâm chính trị, kinh tế, văn hoá của một vùng hoặc cả nước.","Khái niệm: Đô thị là nơi dân cư tập trung đông, hoạt động chủ yếu là công nghiệp, thương mại, dịch vụ; là trung tâm chính trị, kinh tế, văn hoá của một vùng…","Từ khoá cần ghi nhớ: Đô thị;","Mốc sự kiện cần nhớ: Thăng Long là đô thị từ năm 1010 (thời Lý)","Một số đô thị cổ ở Việt Nam: Cổ Loa (kinh đô thời An Dương Vương), Thăng Long (từ năm 1010, thời Lý), Phố Hiến (thế kỉ XVI–XVIII), Hội An (thương cảng quốc tế thế kỉ XVI–XVIII),…","Thời Pháp thuộc, nhiều đô thị mới…: Thời Pháp thuộc, nhiều đô thị mới được xây dựng theo kiểu phương Tây (Hà Nội, Sài Gòn, Hải Phòng, Đà Lạt…)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Thế giới từ năm 1918 đến năm 1945","l":[{"t":"Bài tập nâng cao · Chương 1. Thế giới từ năm 1918 đến năm 1945 (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 2. Việt Nam từ năm 1918 đến năm 1945","l":[{"t":"Bài tập nâng cao · Chương 2. Việt Nam từ năm 1918 đến năm 1945 (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 3. Thế giới từ năm 1945 đến năm 1991","l":[{"t":"Bài tập nâng cao · Chương 3. Thế giới từ năm 1945 đến năm 1991 (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 4. Việt Nam từ năm 1945 đến năm 1975","l":[{"t":"Bài tập nâng cao · Chương 4. Việt Nam từ năm 1945 đến năm 1975 (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương 5. Thế giới từ năm 1991 đến nay","l":[{"t":"Bài tập nâng cao · Chương 5. Thế giới từ năm 1991 đến nay (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 6. Việt Nam từ năm 1976 đến nay","l":[{"t":"Bài tập nâng cao · Chương 6. Việt Nam từ năm 1976 đến nay (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 7. Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá","l":[{"t":"Bài tập nâng cao · Chương 7. Cách mạng khoa học – kĩ thuật và xu thế toàn cầu hoá (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề chung. Đô thị: lịch sử và hiện tại","l":[{"t":"Bài tập nâng cao · Chủ đề chung. Đô thị: lịch sử và hiện tại (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 9","c":[{"t":"Chương 1. Địa lí dân cư Việt Nam","l":[{"t":"Bài 1. Dân tộc và dân số","req":["Trình bày được đặc điểm phân bố các dân tộc Việt Nam; phân tích được sự thay đổi cơ cấu tuổi và giới tính của dân cư."],"sum":["Việt Nam có 54 dân tộc; dân tộc Kinh chiếm khoảng 85% dân số, phân bố chủ yếu ở đồng bằng, trung du và ven biển; các dân tộc thiểu số phân bố chủ yếu ở miền núi và cao nguyên.","Khái niệm: Việt Nam có 54 dân tộc; dân tộc Kinh chiếm khoảng 85% dân số, phân bố chủ yếu ở đồng bằng, trung du và ven biển; các dân tộc thiểu số phân bố chủ…","Từ khoá cần ghi nhớ: 54 dân tộc; dân tộc Kinh; gia tăng dân số; cơ cấu dân số già hoá;","Điểm nhấn ghi nhớ: Năm 2023 khoảng 100 triệu người, đứng thứ 3 Đông Nam Á; dân tộc Kinh chiếm khoảng 85%","Việt Nam là nước đông dân (khoảng…: Việt Nam là nước đông dân (khoảng 100 triệu người năm 2023, đứng thứ 3 Đông Nam Á).","Cơ cấu dân số theo tuổi đang già hoá: Tỉ lệ nhóm 0–14 tuổi giảm, nhóm từ 65 tuổi trở lên tăng; nước ta đang trong thời kì \"cơ cấu dân số vàng\" (nhóm 15–64 tuổi chiếm khoảng 2/3 dân số)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Phân bố dân cư và các loại hình quần cư","req":["Trình bày được sự phân bố dân cư; phân biệt được quần cư thành thị và quần cư nông thôn; nêu được đặc điểm đô thị hoá."],"sum":["Mật độ dân số nước ta cao (khoảng 300 người/km²). Dân cư phân bố không đều: tập trung đông ở đồng bằng, ven biển và đô thị; thưa thớt ở miền núi.","Mật độ dân số nước ta cao (khoảng 300 người/km²): Dân cư phân bố không đều: tập trung đông ở đồng bằng, ven biển và đô thị; thưa thớt ở miền núi.","Từ khoá cần ghi nhớ: Mật độ dân số; phân bố dân cư; quần cư nông thôn; quần cư thành thị;","Điểm nhấn ghi nhớ: Mật độ khoảng 300 người/km²; năm 2023 có 62% dân số nông thôn, 38% thành thị","Khoảng 62% dân số sống ở nông…: Khoảng 62% dân số sống ở nông thôn, 38% ở thành thị (năm 2023), tỉ lệ dân thành thị đang tăng.","Quần cư nông thôn: Mật độ thấp, hoạt động kinh tế chủ yếu là nông, lâm, ngư nghiệp, các điểm dân cư là làng, bản, thôn, ấp… Quần cư thành thị: mật độ cao, hoạt động…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Lao động và việc làm","req":["Trình bày được đặc điểm nguồn lao động, sự chuyển dịch cơ cấu lao động; vấn đề việc làm ở nước ta."],"sum":["Nguồn lao động dồi dào (khoảng 52 triệu người năm 2023), mỗi năm tăng thêm khoảng 1 triệu.","Khái niệm: Nguồn lao động dồi dào (khoảng 52 triệu người năm 2023), mỗi năm tăng thêm khoảng 1 triệu.","Từ khoá cần ghi nhớ: Nguồn lao động; chất lượng lao động; cơ cấu lao động; chuyển dịch; việc làm; thất nghiệp.","Điểm nhấn ghi nhớ: Khoảng 52 triệu lao động (2023), mỗi năm tăng thêm khoảng 1 triệu người","Cơ cấu lao động chuyển dịch: Giảm tỉ trọng nông, lâm, thuỷ sản; tăng tỉ trọng công nghiệp – xây dựng và dịch vụ.","Việc làm là vấn đề kinh tế – xã hội lớn: Thất nghiệp ở thành thị, thiếu việc làm ở nông thôn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Địa lí các ngành kinh tế","l":[{"t":"Bài 5. Nông nghiệp","req":["Phân tích được các nhân tố ảnh hưởng đến sự phát triển và phân bố nông nghiệp; trình bày được sự phát triển và phân bố trồng trọt, chăn nuôi."],"sum":["Nhân tố tự nhiên: đất (phù sa ở đồng bằng – cây lúa; feralit, badan ở miền núi, cao nguyên – cây công nghiệp), khí hậu nhiệt đới ẩm gió mùa, nguồn nước dồi dào, sinh vật phong phú.","Nhân tố tự nhiên: Đất (phù sa ở đồng bằng – cây lúa; feralit, badan ở miền núi, cao nguyên – cây công nghiệp), khí hậu nhiệt đới ẩm gió mùa, nguồn nước dồi dào, sinh…","Từ khoá cần ghi nhớ: Nhân tố tự nhiên; nhân tố kinh tế – xã hội; trồng trọt; chăn nuôi; cây lương thực; cây công nghiệp.","Điểm nhấn ghi nhớ: Đồng bằng sông Cửu Long chiếm hơn 50% sản lượng lúa cả nước","Trồng trọt: Cây lúa là cây lương thực chính, tập trung ở Đồng bằng sông Cửu Long (hơn 50% sản lượng lúa cả nước) và Đồng bằng sông Hồng.","Chăn nuôi: Lợn (ở đồng bằng), trâu, bò (ở miền núi, trung du, duyên hải), gia cầm;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Lâm nghiệp và thuỷ sản","req":["Trình bày được sự phát triển và phân bố lâm nghiệp, thuỷ sản; ý nghĩa của rừng và việc bảo vệ nguồn lợi thuỷ sản."],"sum":["Rừng nước ta gồm rừng đặc dụng, rừng phòng hộ và rừng sản xuất. Độ che phủ rừng khoảng 42% (năm 2023).","Khái niệm: Rừng nước ta gồm rừng đặc dụng, rừng phòng hộ và rừng sản xuất.","Từ khoá cần ghi nhớ: Rừng đặc dụng; rừng phòng hộ; rừng sản xuất;","Điểm nhấn ghi nhớ: Độ che phủ rừng khoảng 42% (2023); bờ biển dài 3 260 km","Thuỷ sản: Điều kiện thuận lợi (bờ biển dài 3 260 km, vùng biển rộng, nhiều ngư trường, nhiều sông, hồ, đầm, vùng nước lợ).","Cần khai thác hợp lí, bảo vệ…: Cần khai thác hợp lí, bảo vệ nguồn lợi thuỷ sản, chống khai thác tận diệt;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Công nghiệp","req":["Phân tích được các nhân tố ảnh hưởng đến phát triển và phân bố công nghiệp; trình bày được sự phát triển và phân bố của một số ngành công nghiệp chủ yếu."],"sum":["Nhân tố: tài nguyên khoáng sản (than ở Quảng Ninh; dầu khí ở thềm lục địa phía nam; bô-xít ở Tây Nguyên), nguồn thuỷ năng; lao động, thị trường, chính sách, vốn và công nghệ, cơ sở hạ tầng.","Nhân tố: Tài nguyên khoáng sản (than ở Quảng Ninh; dầu khí ở thềm lục địa phía nam; bô-xít ở Tây Nguyên), nguồn thuỷ năng; lao động, thị trường, chính sách,…","Từ khoá cần ghi nhớ: Nhân tố phát triển; khai thác nhiên liệu;","Điểm nhấn ghi nhớ: Than ở Quảng Ninh, dầu khí ở Bà Rịa – Vũng Tàu, thuỷ điện Hoà Bình, Sơn La, Lai Châu","Ngành khai thác nhiên liệu: Than (Quảng Ninh), dầu khí (Bà Rịa – Vũng Tàu).","Công nghiệp chế biến lương thực –…: Công nghiệp chế biến lương thực – thực phẩm, dệt may, sản xuất sản phẩm điện tử, máy vi tính là các ngành chủ lực, có giá trị xuất khẩu lớn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Dịch vụ","req":["Trình bày được vai trò, sự phát triển và phân bố của các ngành giao thông vận tải, bưu chính viễn thông, thương mại, du lịch."],"sum":["Dịch vụ gồm dịch vụ tiêu dùng, dịch vụ sản xuất và dịch vụ công. Dịch vụ tập trung ở nơi đông dân và kinh tế phát triển;","Khái niệm: Dịch vụ gồm dịch vụ tiêu dùng, dịch vụ sản xuất và dịch vụ công.","Từ khoá cần ghi nhớ: Dịch vụ tiêu dùng; dịch vụ sản xuất; dịch vụ công; giao thông vận tải; thương mại; bưu chính viễn thông.","Điểm nhấn ghi nhớ: Hà Nội và TP Hồ Chí Minh là hai trung tâm dịch vụ lớn nhất cả nước","Giao thông vận tải: Đường bộ (quốc lộ 1, đường cao tốc Bắc – Nam), đường sắt Thống Nhất, đường biển, đường hàng không, đường sông.","Thương mại: Nội thương phát triển; ngoại thương tăng mạnh, thị trường xuất khẩu lớn là Hoa Kì, Trung Quốc, EU, Nhật Bản, Hàn Quốc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Địa lí các vùng kinh tế – xã hội","l":[{"t":"Bài 12. Vùng Trung du và miền núi phía Bắc","req":["Trình bày được vị trí, đặc điểm tự nhiên, dân cư và thế mạnh kinh tế của vùng Trung du và miền núi phía Bắc."],"sum":["Vùng có diện tích lớn nhất cả nước (khoảng 95 nghìn km²), giáp Trung Quốc, Lào, Đồng bằng sông Hồng, Bắc Trung Bộ và vịnh Bắc Bộ.","Khái niệm: Vùng có diện tích lớn nhất cả nước (khoảng 95 nghìn km²), giáp Trung Quốc, Lào, Đồng bằng sông Hồng, Bắc Trung Bộ và vịnh Bắc Bộ.","Từ khoá cần ghi nhớ: Trung du và miền núi phía Bắc;","Điểm nhấn ghi nhớ: Vùng có diện tích lớn nhất cả nước, khoảng 95 nghìn km²","Thế mạnh: Khai thác khoáng sản (than Quảng Ninh, a-pa-tít Lào Cai…), thuỷ điện (trên sông Đà: Hoà Bình, Sơn La, Lai Châu), trồng cây công nghiệp cận nhiệt và…","Dân cư thưa, nhiều dân tộc ít…: Dân cư thưa, nhiều dân tộc ít người (Tày, Nùng, Thái, Mường, Mông, Dao…)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Vùng Đồng bằng sông Hồng","req":["Trình bày được đặc điểm vị trí, tự nhiên, dân cư; sự phát triển và phân bố các ngành kinh tế của vùng Đồng bằng sông Hồng; vị thế của Thủ đô Hà Nội."],"sum":["Vùng có diện tích khoảng 21 nghìn km², dân số đông nhất cả nước (khoảng 23 triệu), mật độ dân số cao nhất cả nước.","Khái niệm: Vùng có diện tích khoảng 21 nghìn km², dân số đông nhất cả nước (khoảng 23 triệu), mật độ dân số cao nhất cả nước.","Từ khoá cần ghi nhớ: Đồng bằng sông Hồng; mật độ dân số cao nhất; cây vụ đông; khu công nghiệp;","Điểm nhấn ghi nhớ: Diện tích khoảng 21 nghìn km², dân số khoảng 23 triệu, đông nhất cả nước","Kinh tế: Công nghiệp phát triển sớm, nhiều khu công nghiệp (Hà Nội, Hải Phòng, Bắc Ninh…); nông nghiệp là vùng trọng điểm lúa thứ hai, năng suất lúa cao nhất…","Thủ đô Hà Nội là trung tâm…: Thủ đô Hà Nội là trung tâm chính trị – hành chính quốc gia, trung tâm lớn về kinh tế, văn hoá, giáo dục, giao dịch quốc tế."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 14. Vùng Bắc Trung Bộ","req":["Trình bày được vị trí, đặc điểm tự nhiên, dân cư và sự phát triển các ngành kinh tế của vùng Bắc Trung Bộ."],"sum":["Vùng lãnh thổ hẹp ngang, kéo dài từ dãy Tam Điệp đến dãy Bạch Mã; phía tây là dãy Trường Sơn Bắc, phía đông là biển.","Khái niệm: Vùng lãnh thổ hẹp ngang, kéo dài từ dãy Tam Điệp đến dãy Bạch Mã; phía tây là dãy Trường Sơn Bắc, phía đông là biển.","Từ khoá cần ghi nhớ: Bắc Trung Bộ; dãy Tam Điệp; dãy Bạch Mã;","Điểm nhấn ghi nhớ: Lãnh thổ hẹp ngang, từ dãy Tam Điệp đến dãy Bạch Mã; chịu gió phơn Tây Nam khô nóng đầu hạ","Khí hậu: Chịu ảnh hưởng gió phơn Tây Nam khô nóng vào đầu hạ; nhiều thiên tai (bão, lũ, hạn hán, cát bay).","Du lịch phát triển với nhiều di sản: Cố đô Huế, Phong Nha – Kẻ Bàng, Thành nhà Hồ… Kinh tế biển, khu kinh tế ven biển (Nghi Sơn, Vũng Áng…) đang phát triển."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 16. Vùng Duyên hải Nam Trung Bộ và Tây Nguyên","req":["Trình bày được đặc điểm tự nhiên, dân cư và thế mạnh kinh tế của Duyên hải Nam Trung Bộ và Tây Nguyên; vấn đề phát triển kinh tế biển, cây công nghiệp lâu năm."],"sum":["Duyên hải Nam Trung Bộ: dải đồng bằng hẹp ven biển, nhiều vũng vịnh, bãi biển đẹp (Nha Trang, Mũi Né…); thế mạnh kinh tế biển: khai thác và nuôi trồng thuỷ sản, làm muối (Sa Huỳnh, Cà Ná), du lịch…","Duyên hải Nam Trung Bộ: Dải đồng bằng hẹp ven biển, nhiều vũng vịnh, bãi biển đẹp (Nha Trang, Mũi Né…); thế mạnh kinh tế biển: khai thác và nuôi trồng thuỷ sản, làm muối…","Từ khoá cần ghi nhớ: Duyên hải Nam Trung Bộ;","Điểm nhấn ghi nhớ: Tây Nguyên không giáp biển, có đất ba-dan màu mỡ;","Tây Nguyên: Không giáp biển, gồm các cao nguyên xếp tầng, đất badan màu mỡ, khí hậu cận xích đạo có một mùa khô sâu sắc.","Tây Nguyên là địa bàn cư trú…: Tây Nguyên là địa bàn cư trú của nhiều dân tộc (Gia-rai, Ê-đê, Ba-na, Xơ-đăng…), có không gian văn hoá Cồng chiêng Tây Nguyên là di sản văn hoá phi…"],"e":["Hay nhầm: Không phải cây công nghiệp."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Vùng Đông Nam Bộ","req":["Trình bày được đặc điểm tự nhiên, dân cư và sự phát triển các ngành kinh tế của vùng Đông Nam Bộ; vị thế của Thành phố Hồ Chí Minh."],"sum":["Vùng có diện tích khoảng 23,5 nghìn km², địa hình thoải, đất badan và đất xám; khí hậu cận xích đạo; có thềm lục địa giàu dầu khí.","Khái niệm: Vùng có diện tích khoảng 23,5 nghìn km², địa hình thoải, đất badan và đất xám; khí hậu cận xích đạo; có thềm lục địa giàu dầu khí.","Từ khoá cần ghi nhớ: Đông Nam Bộ; dầu khí; cao su;","Điểm nhấn ghi nhớ: Vùng kinh tế phát triển nhất cả nước; cao su đứng đầu cả nước","Kinh tế phát triển nhất cả nước: Công nghiệp (dầu khí, điện, điện tử, cơ khí, hoá chất, chế biến thực phẩm) tập trung ở TP Hồ Chí Minh, Bình Dương, Đồng Nai, Bà Rịa – Vũng Tàu; cây…","Thành phố Hồ Chí Minh là trung…: Thành phố Hồ Chí Minh là trung tâm kinh tế, tài chính, thương mại lớn nhất cả nước, đầu mối giao thông quan trọng (cảng Sài Gòn, sân bay Tân Sơn…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Vùng Đồng bằng sông Cửu Long","req":["Trình bày được đặc điểm tự nhiên, dân cư và sự phát triển các ngành kinh tế của vùng Đồng bằng sông Cửu Long; tác động của biến đổi khí hậu đến vùng."],"sum":["Vùng có diện tích khoảng 40,9 nghìn km², địa hình thấp, bằng phẳng; đất phù sa ngọt ven sông Tiền, sông Hậu, đất phèn, đất mặn; khí hậu cận xích đạo; mạng lưới sông ngòi, kênh rạch chằng chịt.","Khái niệm: Vùng có diện tích khoảng 40,9 nghìn km², địa hình thấp, bằng phẳng;","Từ khoá cần ghi nhớ: Đồng bằng sông Cửu Long;","Điểm nhấn ghi nhớ: Vùng trọng điểm lúa lớn nhất cả nước, hơn 50% sản lượng lúa; dẫn đầu nuôi trồng thuỷ sản","Kinh tế: Vùng trọng điểm lúa lớn nhất cả nước (hơn 50% sản lượng lúa, đóng góp phần lớn gạo xuất khẩu); dẫn đầu nuôi trồng thuỷ sản (cá tra, tôm); cây ăn quả…","Thách thức: Biến đổi khí hậu, nước biển dâng, xâm nhập mặn, sạt lở bờ sông, thiếu nước ngọt mùa khô."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 21. Phát triển tổng hợp kinh tế và bảo vệ tài nguyên, môi trường biển, đảo","req":["Trình bày được các ngành kinh tế biển; ý nghĩa phát triển tổng hợp kinh tế biển; sự cần thiết bảo vệ tài nguyên, môi trường biển, đảo."],"sum":["Vùng biển nước ta rộng khoảng 1 triệu km², bờ biển dài 3 260 km, có hơn 4 000 hòn đảo; gồm nội thuỷ, lãnh hải (rộng 12 hải lí), vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế (200 hải lí tính từ…","Khái niệm: Vùng biển nước ta rộng khoảng 1 triệu km², bờ biển dài 3 260 km, có hơn 4 000 hòn đảo; gồm nội thuỷ, lãnh hải (rộng 12 hải lí), vùng tiếp giáp lãnh…","Từ khoá cần ghi nhớ: Vùng biển; hải đảo; nội thuỷ; lãnh hải; vùng đặc quyền kinh tế; thềm lục địa; khai thác biển; bảo vệ môi trường biển.","Điểm nhấn ghi nhớ: Vùng biển rộng khoảng 1 triệu km², có hơn 4 000 hòn đảo; vùng đặc quyền kinh tế rộng 200 hải lí","Các ngành kinh tế biển: Khai thác, nuôi trồng và chế biến hải sản; du lịch biển – đảo; khai thác khoáng sản biển (dầu khí, muối, cát, ti-tan); giao thông vận tải biển.","Phát triển tổng hợp kinh tế biển…: Phát triển tổng hợp kinh tế biển giúp khai thác hiệu quả tài nguyên, bảo vệ môi trường và khẳng định chủ quyền."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","req":["Trình bày được quá trình xác lập và thực thi chủ quyền của Việt Nam đối với quần đảo Hoàng Sa và Trường Sa; vai trò của Biển Đông; trách nhiệm của công dân."],"sum":["Biển Đông có vị trí chiến lược về giao thông hàng hải quốc tế, giàu tài nguyên (dầu khí, hải sản), có ý nghĩa quan trọng về quốc phòng – an ninh đối với Việt Nam.","Khái niệm: Biển Đông có vị trí chiến lược về giao thông hàng hải quốc tế, giàu tài nguyên (dầu khí, hải sản), có ý nghĩa quan trọng về quốc phòng – an ninh đối…","Từ khoá cần ghi nhớ: Chủ quyền;","Điểm nhấn ghi nhớ: Việt Nam xác lập chủ quyền hoà bình, liên tục ít nhất từ thế kỉ XVII thông qua hải đội Hoàng Sa, Bắc Hải","Nhà nước Việt Nam là nhà nước…: Nhà nước Việt Nam là nhà nước đầu tiên xác lập và thực thi chủ quyền đối với quần đảo Hoàng Sa và Trường Sa một cách hoà bình, liên tục, phù hợp…","Hiện nay, quần đảo Hoàng Sa thuộc…: Hiện nay, quần đảo Hoàng Sa thuộc thành phố Đà Nẵng, quần đảo Trường Sa thuộc tỉnh Khánh Hoà."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Địa lí dân cư Việt Nam","l":[{"t":"Bài tập nâng cao · Chương 1. Địa lí dân cư Việt Nam (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 2. Địa lí các ngành kinh tế","l":[{"t":"Bài tập nâng cao · Chương 2. Địa lí các ngành kinh tế (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 3. Địa lí các vùng kinh tế – xã hội","l":[{"t":"Bài tập nâng cao · Chương 3. Địa lí các vùng kinh tế – xã hội (14 câu)","q":{"n":14,"lv":{"Nâng cao":14}}}]},{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Bài tập nâng cao · Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]}]};
